window.HB_TR["proverbs"]["ur"]=["1۔ سلیمان، داؤد کے بیٹے، اسرائیل کے بادشاہ کی کہاوتیں؛\n2۔ حکمت اور تعلیم کو جاننا؛ سمجھ بوجھ کے الفاظ کو محسوس کرنا؛\n3۔ حکمت، انصاف، فیصلے اور انصاف کی تعلیم حاصل کرنا؛ {ایکویٹی: عبرانی۔ ایکویٹیز}\n4۔ سادہ چیزوں کو نزاکت دینا، نوجوان کے علم اور احتیاط کو دینا۔ {صوابدید: یا، مشورہ}\n5۔ ایک دانا {انسان} سنے گا، اور سیکھنے میں اضافہ کرے گا؛ اور سمجھدار شخص دانشمندانہ مشورے حاصل کرے گا:\n6۔ کسی کہاوت کو سمجھنا، اور اس کی تشریح کرنا؛ دانا کے الفاظ، اور ان کے تاریک اقوال۔ {تشریح: یا، ایک بلیغ تقریر}\n7. خداوند کا خوف {ہے} علم کی ابتدا: {لیکن} بیوقوف حکمت اور تعلیم سے نفرت کرتے ہیں۔ {آغاز: یا، اصل حصہ}\n8۔ میرے بیٹے، اپنے والد کی ہدایت سنو، اور اپنی ماں کے قانون کو مت چھوڑو:\n9۔ کیونکہ وہ تمہارے سر کے لیے فضل کا زیور ہوں گے، اور تمہارے گلے میں زنجیریں ہوں گی۔ {an...: عبرانی۔ ایک اضافہ}\n10۔ میرے بیٹے، اگر گناہ گار تمہیں لبھاتے ہیں تو رضامندی نہ دینا۔\n11۔ اگر وہ کہیں، ہمارے ساتھ آؤ، خون کا انتظار کرو، تو بے گناہوں کے لیے بے وجہ چھپ کر رہیں:\n12۔ آؤ انہیں زندہ نگل لیں جیسے قبر؛ اور مکمل طور پر، جیسے وہ لوگ جو گڑھے میں جاتے ہیں:\n13۔ ہم ہر قیمتی چیز تلاش کریں گے، اپنے گھروں کو مال غنیمت سے بھر دیں گے:\n14۔ اپنے حصے میں ہمارے درمیان ڈال دو؛ آئیے ہم سب کے پاس ایک پرس ہو:\n15۔ میرے بیٹے، ان کے راستے میں نہ چلو؛ اپنے قدم ان کے راستے سے ہٹا لو:\n16۔ کیونکہ ان کے قدم برائی کی طرف دوڑتے ہیں، اور جلدی خون بہاتے ہیں۔\n17. یقینا جال کسی بھی پرندے کی نظر میں بے سود بچھا دیا جاتا ہے۔ {میں...: عبرانی میں۔ ہر اس چیز کی آنکھوں میں جس کے پر ہیں}\n18۔ اور وہ اپنے خون کا انتظار کر رہے تھے؛ وہ اپنی {اپنی} زندگیوں کے لیے نجی طور پر چھپے رہتے ہیں۔\n19. اسی طرح ہر اس شخص کے طریقے ہیں جو فائدے کا لالچی ہے؛ {جو} ان کے مالکان کی جان لے لیتا ہے۔\n20۔ حکمت باہر پکارتی ہے؛ وہ گلیوں میں اپنی آواز نکالتی ہے: {حکمت: عبرانی۔ حکمت، یعنی، بہترین حکمت}\n21۔ وہ مرکزی جگہ پر، دروازوں کے دروازوں میں پکارتی ہے: شہر میں وہ اپنے الفاظ ادا کرتی ہے، {کہتی ہے}،\n22. اے سادہ لوگو، تم کتنی دیر تک سادگی سے محبت کرو گے؟ اور طنزیہ اپنی حقارت میں خوش ہوتے ہیں، اور بے وقوف علم سے نفرت کرتے ہیں؟\n23. میری سرزنش پر تمہیں پلٹا دوں: دیکھو، میں اپنی روح تم پر نازل کروں گا، میں اپنے الفاظ تمہیں بتاؤں گا۔\n24۔ کیونکہ میں نے بلایا اور تم نے انکار کر دیا؛ میں نے اپنا ہاتھ بڑھایا ہے، اور کوئی آدمی نظر نہیں آیا؛\n25۔ لیکن تم نے میری تمام نصیحتیں بے اثر کر دی ہیں، اور میری کوئی تنقید نہیں کرتے:\n26۔ میں بھی تمہاری آفت پر ہنسوں گا؛ جب تمہارا خوف آئے گا تو میں مذاق اڑاؤں گا؛\n27۔ جب تمہارا خوف ویرانی کی صورت میں آئے، اور تمہاری تباہی طوفان کی طرح آئے؛ جب تم پر مصیبت اور اذیت آتی ہے۔\n28۔ پھر وہ مجھے پکاریں گے، لیکن میں جواب نہیں دوں گا؛ وہ مجھے جلدی تلاش کریں گے، لیکن مجھے نہیں پائیں گے:\n29۔ کیونکہ وہ علم سے نفرت کرتے تھے، اور خداوند کے خوف کو نہیں چنا:\n30۔ انہوں نے میری نصیحت کو قبول نہیں کیا: وہ میری تمام سرزنش سے نفرت کرتے تھے۔\n31۔ اسی لیے وہ اپنے طریقے کے پھل سے کھائیں گے، اور اپنی مرضی سے بھر جائیں گے۔\n32۔ کیونکہ سادہ لوگوں کا منہ موڑنا انہیں مار ڈالے گا، اور بے وقوفوں کی خوشحالی انہیں تباہ کر دے گی۔ {گھومنا...: یا، آسان باتیں}\n33. لیکن جو بھی میری بات سنے گا، وہ محفوظ رہے گا، اور برائی کے خوف سے خاموش رہے گا۔","1۔ میرے بیٹے، اگر تم میرے الفاظ قبول کرو اور میرے احکامات اپنے ساتھ چھپا دو؛\n2۔ تاکہ تم اپنے کان کو حکمت کی طرف مائل کرو، {اور} اپنے دل کو سمجھ میں لگا دو؛\n3۔ ہاں، اگر تم علم کے لیے پکار رہے ہو، {اور} سمجھنے کے لیے اپنی آواز بلند کرو؛ {liftest...: عبرانی اپنی آواز دو}\n4۔ اگر تم اسے چاندی کی طرح تلاش کرو، اور اسے چھپے ہوئے خزانے کی طرح تلاش کرو؛\n5۔ پھر تم خداوند کے خوف کو سمجھو گے، اور خدا کا علم پاؤ گے۔\n6۔ کیونکہ خداوند حکمت دیتا ہے: اس کے منہ سے علم اور سمجھ آتی ہے۔\n7۔ وہ نیک لوگوں کے لیے صحیح حکمت پیش کرتا ہے: {وہ} ان لوگوں کے لیے بکلر ہے جو سیدھے چلتے ہیں۔\n8۔ وہ فیصلے کے راستے برقرار رکھتا ہے، اور اپنے مقدسین کے راستے کو برقرار رکھتا ہے۔\n9۔ پھر تم راستبازی، انصاف اور انصاف کو سمجھو گے؛ {ہاں}، ہر اچھا راستہ۔\n10۔ جب حکمت تمہارے دل میں داخل ہو، اور علم تمہاری روح کے لیے خوشگوار ہو؛\n11۔ صوابدید آپ کو محفوظ رکھے گی، سمجھ بوجھ آپ کو برقرار رکھے گی:\n12۔ تاکہ تمہیں برے انسان کے راستے سے بچا سکوں، اس آدمی سے جو بدتمیز باتیں کرتا ہے؛\n13۔ جو راستبازی کے راستے چھوڑ کر تاریکی کے راستوں پر چلتے ہیں؛\n14۔ جو برائی کرنے پر خوش ہوتے ہیں، {اور} بدکاروں کی شرارت میں خوش ہوتے ہیں؛\n15۔ جن کے طریقے ٹیڑھے ہیں، اور وہ اپنے راستوں میں بھٹکتے ہیں:\n16۔ تمہیں اس اجنبی عورت سے بچانے کے لیے، {حتیٰ کہ} اس اجنبی سے بھی جو اپنی باتوں سے خوشامد کرتا ہے؛\n17۔ جو اپنی جوانی کی رہنما کو چھوڑ دیتی ہے، اور اپنے خدا کے عہد کو ترک کرتی ہے۔\n18۔ کیونکہ اس کا گھر موت کی طرف مائل ہوتا ہے، اور اس کے راستے مردوں کی طرف جاتے ہیں۔\n19۔ جو لوگ دوبارہ اس کی طرف جاتے ہیں، وہ زندگی کے راستے اختیار نہیں کرتے۔\n20. تاکہ تم نیک لوگوں کی راہ میں چل سکو، اور نیک راستوں کے راستے پر قائم رہو۔\n21. کیونکہ نیک لوگ زمین میں رہیں گے، اور کامل لوگ اس میں رہیں گے۔\n22۔ لیکن بدکاروں کو زمین سے کاٹ دیا جائے گا، اور مجرموں کو وہاں سے نکال دیا جائے گا۔ {روٹڈ: یا، اٹھا ہوا}","1۔ میرے بیٹے، میرا قانون مت بھولو؛ لیکن اپنے دل کو میرے احکامات پر قائم رکھ:\n2. لمبائی دنوں، لمبی عمر اور سکون کے لیے، وہ آپ میں اضافہ کریں گے۔ {لمبا...: عبرانی۔ زندگی کے سال}\n3۔ رحم اور سچائی کو تمہیں چھوڑنے نہ دو: انہیں اپنی گردن میں باندھ دو؛ انہیں اپنے دل کی میز پر لکھو:\n4. اسی طرح تم خدا اور انسان کی نظر میں فضل اور سمجھ پاؤ گے۔ {اچھائی...: یا، اچھی کامیابی}\n5. خداوند پر پورے دل سے بھروسہ کرو؛ اور اپنی سمجھ کی طرف نہ جھکاؤ۔\n6۔ اپنی تمام راہوں میں اسے تسلیم کرو، اور وہ تمہارے راستے کی رہنمائی کرے گا۔\n7۔ اپنی آنکھوں میں دانا نہ بنو: خداوند سے ڈرو اور برائی سے دور رہو۔\n8۔ یہ تمہاری ناف کی صحت ہوگی، اور تمہاری ہڈیوں کے لیے گودا ہوگا۔ {صحت: عبرانی۔ طب} {marrow: Hebrew. پانی دینا، یا نمی کرنا}\n9۔ خداوند کی عزت اپنے مال اور اپنی تمام کامیابیوں کے پہلے پھلوں سے کر:\n10۔ اسی طرح تمہارے کھیت بھرے ہوں گے، اور تمہارے پریس نئی شراب سے پھٹ جائیں گے۔\n11۔ میرے بیٹے، خداوند کی نصیحت کو حقیر نہ سمجھو؛ ان کی اصلاح سے بھی نہ تھکیں:\n12۔ جس کے لیے خداوند محبت کرتا ہے، وہ اصلاح کرتا ہے؛ حتیٰ کہ ایک باپ کی طرح، بیٹا {جس سے} وہ خوش ہوتا ہے۔\n13. خوش قسمت {ہے} وہ شخص {جو} حکمت پاتا ہے، اور وہ شخص {جو} سمجھ پاتا ہے۔ {جو ملتا ہے...: عببرانی۔ جو سمجھ بوجھ کو باہر نکالتا ہے}\n14۔ کیونکہ اس کی تجارت چاندی کے مال سے بہتر ہے، اور اس کا فائدہ عمدہ سونے سے بہتر ہے۔\n15۔ وہ یاقوت سے بھی زیادہ قیمتی ہے: اور وہ تمام چیزیں جو تم چاہو اس سے موازنہ نہیں کی جا سکتیں۔\n16. دنوں کی لمبائی {ہے} اس کے دائیں ہاتھ میں؛ {اور} اس کے بائیں ہاتھ میں دولت اور عزت۔\n17. اس کے طریقے خوش دلی کے طریقے ہیں، اور اس کے تمام راستے سکون ہیں۔\n18. وہ ان لوگوں کے لیے زندگی کا درخت ہے جو اس پر قابض ہیں: اور ہر وہ خوش ہے جو اسے سنبھالتا ہے۔\n19۔ خداوند نے حکمت سے زمین کی بنیاد رکھی ہے؛ سمجھ بوجھ سے اس نے آسمان قائم کیے ہیں۔ {قائم: یا، تیار}\n20۔ اس کے علم کے مطابق گہرائیاں ٹوٹ جاتی ہیں، اور بادل شبنم میں گرتے ہیں۔\n21۔ میرے بیٹے، انہیں تیری آنکھوں سے نہ ہٹا: عقل اور احتیاط رکھو:\n22۔ اسی طرح وہ تمہاری روح کی زندگی ہوں گے، اور تمہاری گردن پر فضل بھی۔\n23۔ پھر تم اپنے راستے میں محفوظ چلو، اور تمہارا قدم لڑکھڑائے گا نہیں۔\n24۔ جب تم لیٹ جاؤ گے، تو ڈرو نہیں: ہاں، تم لیٹو گے، اور تمہاری نیند میٹھی ہوگی۔\n25۔ اچانک خوف سے نہ ڈرو، نہ ہی بدکاروں کی ویرانی سے جب وہ آتا ہے۔\n26۔ کیونکہ خداوند تمہارا اعتماد ہوگا، اور تمہارے پاؤں کو پکڑے جانے سے بچائے گا۔\n27۔ ان سے بھلائی نہ روکیں جن کے لیے یہ حق ہے، جب کہ یہ آپ کے ہاتھ میں ہے کہ وہ کر سکیں۔ {وہ...: عبرانی۔ اس کے مالکان}\n28۔ اپنے پڑوسی کو مت کہنا، جاؤ اور دوبارہ آؤ، اور کل میں دوں گا؛ جب وہ تمہارے پاس ہو۔\n29۔ اپنے پڑوسی کے خلاف برائی نہ کرو، کیونکہ وہ تمہارے ساتھ سکون سے رہتا ہے۔ {منصوبہ بندی...: یا، برائی کی مشق نہ کرو}\n30۔ بغیر وجہ کے کسی آدمی کے ساتھ کوشش نہ کرو، اگر اس نے تمہیں نقصان نہ پہنچایا۔\n31. ظالم سے حسد نہ کرو، اور اس کے راستے نہ چننا۔ {ظالم: عبرانی۔ تشدد کا آدمی}\n32. کیونکہ بدکار خداوند کے لیے مکروہ ہے: لیکن اس کا راز راستبازوں کے پاس ہے۔\n33۔ خداوند کی لعنت {ہے} بدکاروں کے گھر میں: لیکن وہ راستوں کی رہائش کو برکت دیتا ہے۔\n34۔ یقینا وہ طنزیہ لوگوں کو حقیر سمجھتا ہے، لیکن وہ کمتر لوگوں کو فضل دیتا ہے۔\n35۔ عقلمند جلال کے وارث ہوں گے، لیکن بے وقوفوں کی ترقی شرم ہوگی۔ {ہوگا...: عبرانی۔ بیوقوفوں کو بلند کرو","1. اے بچوں، ایک باپ کی تعلیم سنو، اور سمجھ بوجھ جاننے کی کوشش کرو۔\n2۔ کیونکہ میں تمہیں اچھا عقیدہ دیتا ہوں، تم میرے قانون کو ترک نہ کرو۔\n3. کیونکہ میں اپنے والد کا بیٹا تھا، نرم دل اور اپنی ماں کی نظر میں واحد {محبوب}۔\n4۔ اس نے مجھے بھی سکھایا، اور کہا، اپنے دل کو میرے الفاظ یاد رکھے: میرے احکامات کی پاسداری کرو اور زندہ رہو۔\n5. حکمت حاصل کریں، سمجھ بوجھ حاصل کریں: اسے نہ بھولیں؛ میرے الفاظ سے کوئی انکار نہیں ہوتا۔\n6۔ اسے نہ چھوڑو، اور وہ تمہیں محفوظ رکھے گی: اس سے محبت کرو، اور وہ تمہیں سنبھالے گی۔\n7. حکمت سب سے اہم چیز ہے؛ {لہٰذا} حکمت حاصل کرو: اور اپنی پوری حاصل کے ساتھ سمجھ حاصل کرو۔\n8۔ اسے بلند کرو، اور وہ تمہیں ترقی دے گی: وہ تمہیں عزت دے گی، جب تم اسے گلے لگاؤ گے۔\n9۔ وہ تمہارے سر کو فضل کا زیور دے گی: جلال کا تاج وہ تمہیں دے گی۔ {ایک تاج...: یا، وہ تمہیں جلال کا تاج دے گی}\n10۔ اے میرے بیٹے، سن اور میری باتیں قبول کرو؛ اور تمہاری زندگی کے سال بہت ہوں گے۔\n11۔ میں نے تمہیں حکمت کے راستے میں سکھایا ہے؛ میں نے تمہیں صحیح راستوں پر رہنمائی کی ہے۔\n12۔ جب تم جاؤ گے، تمہارے قدم تنگ نہیں ہوں گے؛ اور جب تم سب سے زیادہ دوڑو گے، تو لڑکھڑاؤ نہیں گے۔\n13۔ تعلیم کو مضبوطی سے تھامنا؛ {اسے} کو نہ جانے دو: اسے رکھو؛ کیونکہ وہ تمہاری زندگی ہے۔\n14. بدکاروں کے راستے میں نہ جاؤ، اور برے لوگوں کے راستے میں نہ جاؤ۔\n15. اس سے بچیں، اس کے پاس سے نہ گزریں، اس سے منہ موڑ لیں اور چلے جائیں۔\n16۔ کیونکہ وہ سوتے نہیں، جب تک کہ انہوں نے شرارت نہ کی ہو؛ اور ان کی نیند چھین لی جاتی ہے، جب تک کہ وہ {کچھ} کو گرنے پر مجبور نہ کریں۔\n17۔ کیونکہ وہ برائی کی روٹی کھاتے ہیں، اور تشدد کی شراب پیتے ہیں۔\n18. لیکن راستوں کا راستہ چمکتی ہوئی روشنی کی طرح ہے، جو کامل دن تک زیادہ چمکتی ہے۔\n19۔ بدکاروں کا راستہ اندھیرے کی طرح ہے: وہ نہیں جانتے کہ وہ کس چیز میں ٹھوکر کھاتے ہیں۔\n20. میرے بیٹے، میرے الفاظ پر دھیان دو؛ میری باتوں کی طرف مائل ہو جاؤ۔\n21۔ وہ تیری آنکھوں سے نہ ہٹیں؛ انہیں اپنے دل کے بیچ میں رکھو۔\n22۔ کیونکہ وہ ان لوگوں کے لیے زندگی ہیں جو انہیں پاتے ہیں، اور ان کے تمام جسم کے لیے صحت۔ {صحت: عبرانی۔ میڈیسن}\n23۔ اپنے دل کو پوری محنت سے سنبھالو؛ کیونکہ اس میں زندگی کے مسائل ہیں۔ {ساتھ...: عبوری۔ سب سے بڑھ کر}\n24۔ اپنے آپ سے ایک بگڑا ہوا منہ ہٹا دو، اور بگڑے ہوئے ہونٹ اپنے سے دور رکھو۔ {ایک طرف اشارہ...: عبرانی۔ منہ کی شرارت اور ہونٹوں کی بے ترتیبی}\n25۔ اپنی آنکھیں سیدھے دیکھتی رہیں، اور اپنی پلکیں سیدھی سامنے دیکھیں۔\n26۔ اپنے قدموں کے راستے پر غور کرو، اور اپنے تمام راستے قائم کرو۔ {آؤ...: یا، تمہارے تمام راستے درست ہو جائیں گے}\n27۔ نہ دائیں ہاتھ کی طرف مڑو نہ بائیں طرف: اپنا پاؤں برائی سے ہٹا لو۔","1۔ میرے بیٹے، میری حکمت کا خیال رکھو، {اور} میری سمجھ کے سامنے اپنا کان جھک جا:\n2. تاکہ تم احتیاط کا خیال رکھو، اور تمہارے ہونٹ علم کو برقرار رکھ سکیں۔\n3. کیونکہ ایک اجنبی عورت کے ہونٹ {شہد کی چھتے} کی طرح گر جاتے ہیں، اور اس کا منہ {تیل} سے بھی ہموار ہو جاتا ہے: {منہ: عبرانی۔ ذائقہ}\n4۔ لیکن اس کا انجام ورم ووڈ کی طرح کڑوا، دو دھاری تلوار کی طرح تیز۔\n5. اس کے پاؤں نیچے جا کر مر جاتے ہیں؛ اس کے قدم جہنم پر جم جاتے ہیں۔\n6۔ اگر تم زندگی کے راستے پر غور نہ کرو، اس کے راستے قابل حرکت ہیں، {کہ} تم انہیں نہیں جان سکتے۔\n7. اب میری بات سنو، اے بچوں، اور میرے منہ کی باتوں سے نہ ہٹو۔\n8۔ اس سے دور ہو جاؤ، اور اس کے گھر کے دروازے کے قریب مت آؤ:\n9۔ کہیں تم اپنی عزت دوسروں کو نہ دو، اور اپنی عمر ظالموں کو نہ دو:\n10۔ تاکہ اجنبی تمہاری دولت سے بھر نہ جائیں؛ اور تمہاری محنت اجنبی کے گھر میں ہوگی؛ {تیری دولت: عبرانی۔ تیری طاقت}\n11۔ اور تم آخر میں سوگ مناتے ہو، جب تمہارا جسم اور جسم کھا جاتے ہیں،\n12۔ اور کہو، میں نے تعلیم سے کتنا نفرت کی، اور دل نے سرزنش سے نفرت کی؛\n13۔ اور نہ میں نے اپنے اساتذہ کی آواز مانی، نہ ہی ان لوگوں کی طرف توجہ دی جنہوں نے مجھے سکھایا!\n14۔ میں تقریبا تمام برائی میں جماعت اور اجتماع کے درمیان تھا۔\n15۔ اپنے ذخیرے سے پانی پیو، اور اپنے کنویں سے بہتا پانی۔\n16۔ تمہارے چشمے باہر بکھر جائیں، اور گلیوں میں پانی کی ندیاں بہاؤ۔\n17۔ وہ صرف تمہارے اپنے ہوں، اور تمہارے ساتھ اجنبی نہ ہوں۔\n18۔ تمہارا چشمہ بابرکت ہو: اور اپنی جوانی کی بیوی کے ساتھ خوشی مناؤ۔\n19۔ {اسے محبت کرنے والی ہرن اور خوشگوار ہرو کی طرح بنے؛ اس کے سینے ہمیشہ تمہیں تسکین دیں؛ اور ہمیشہ اس کی محبت کے سحر میں مبتلا رہو۔ {مطمئن...: عبرانی۔ تمہیں پانی دو} {ہو تو...: عبرانی۔ ارے تم ہمیشہ اس کی محبت میں رہتے ہو}\n20. اور میرے بیٹے، کیوں تم ایک اجنبی عورت کے ساتھ محبت کرو گے، اور ایک اجنبی کی بانہوں میں کیوں آؤ گے؟\n21۔ کیونکہ انسان کے طریقے خداوند کی آنکھوں کے سامنے ہیں، اور وہ اپنے تمام کاموں پر غور کرتا ہے۔\n22۔ اس کے اپنے گناہوں سے بدکار خود آ جائے گا، اور وہ اپنے گناہوں کی رسیوں سے جکڑ جائے گا۔ {گناہ: عبرانی۔ گناہ}\n23۔ وہ بغیر تعلیم کے مر جائے گا؛ اور اپنی حماقت کی عظمت میں وہ گمراہ ہو جائے گا۔","1۔ میرے بیٹے، اگر تم اپنے دوست کے لیے ضمانت رکھتے ہو، {اگر} تم نے کسی اجنبی کے ساتھ ہاتھ مارا ہے،\n2. تم اپنے منہ کے الفاظ میں پھنس گئے ہو، تم اپنے منہ کے الفاظ میں پھنس گئے ہو۔\n3. یہ ابھی کرو، میرے بیٹے، اور جب تم اپنے دوست کے ہاتھ میں آؤ تو خود کو نجات دے؛ جاؤ، اپنے آپ کو عاجز کرو، اور اپنے دوست کو یقینی بناؤ۔ {اور...: یا، یوں تم اپنے دوست کے ساتھ غالب آؤ گے}\n4. اپنی آنکھوں کو نیند نہ دو، نہ اپنی پلکوں کو نیند دو۔\n5. اپنے آپ کو شکاری کے ہاتھ سے ایک رو کی طرح اور شکاری کے ہاتھ سے پرندے کی طرح بچاؤ۔\n6. چیونٹی کے پاس جاؤ، تم سست؛ اس کے طریقے سوچیں، اور دانا بنو:\n7۔ جس کے بغیر رہنما، نگران یا حکمران نہ ہو،\n8۔ گرمیوں میں اس کا گوشت فراہم کرے، {اور} فصل کی کٹائی میں اس کا کھانا جمع کرے۔\n9. تم کتنی دیر سوؤ گے، اے سست؟ تم کب اپنی نیند سے جاگو گے؟\n10۔ {ابھی} تھوڑی نیند، تھوڑی نیند، ہاتھ جوڑ کر سونا:\n11. اسی طرح تمہاری غربت ایک سفر کی طرح آئے گی، اور تمہاری خواہش ایک مسلح آدمی کی طرح ہوگی۔\n12۔ ایک شرارتی شخص، ایک بدکار آدمی، منہ بگڑاتا ہے۔\n13۔ وہ اپنی آنکھوں سے آنکھ مارتا ہے، اپنے پیروں سے بولتا ہے، وہ اپنی انگلیوں سے تعلیم دیتا ہے؛\n14. شرارت اس کے دل میں ہے، وہ مسلسل شرارت کرتا ہے؛ وہ اختلاف پیدا کرتا ہے۔ {سوئیتھ: عبرانی۔ Casteth Forth}\n15۔ اس لیے اس کی آفت اچانک آئے گی؛ اچانک وہ بغیر کسی علاج کے ٹوٹ جائے گا۔\n16. یہ چھ {چیزیں} خدا سے نفرت کرتا ہے: ہاں، سات {ہیں} اس کے لیے مکروہ ہیں: {تو...: عبرانی۔ اس کی روح کی}\n17۔ فخر بھری نظر، جھوٹی زبان، اور معصوم خون بہانے والے ہاتھ {ایک فخر...: عبرانی۔ مغرور آنکھیں}\n18۔ ایک دل جو برے خیالات بناتا ہے، ایسے قدم جو شرارتوں کی طرف دوڑتے ہیں،\n19۔ جھوٹا گواہ جو جھوٹ بولتا ہے، اور جو بھائیوں میں اختلاف پیدا کرتا ہے۔\n20۔ میرے بیٹے، اپنے باپ کے حکم کی پیروی کرو، اور اپنی ماں کے قانون کو نہ چھوڑو:\n21. انہیں اپنے دل پر مسلسل باندھ دو، {اور} اپنے گلے میں باندھ دو۔\n22۔ جب تم جاؤ گے، یہ تمہیں لے جائے گا؛ جب تم سو جاؤ گے، یہ تمہیں سنبھالے گا؛ اور {جب} تم جاگو گے، یہ تم سے بات کرے گا۔\n23۔ کیونکہ حکم {ہے} ایک چراغ ہے؛ اور قانون {ہے} روشنی ہے؛ اور تعلیم کی سرزنش {ہیں} طرز زندگی: {چراغ: یا، موم بتی}\n24۔ تمہیں اس بری عورت سے بچانے کے لیے، ایک اجنبی عورت کی زبان کی چاپلوسی سے۔ {یا اس عجیب زبان کی}\n25۔ اپنے دل میں اس کی خوبصورتی کی خواہش نہ رکھو؛ نہ ہی وہ تمہیں اپنی پلکوں سے لے جانے دے۔\n26۔ کیونکہ ایک بدکار عورت کے ذریعے {ایک مرد کو روٹی کے ٹکڑے تک لایا جاتا ہے}: اور زنا کرنے والی قیمتی زندگی کی تلاش کرے گی۔ {زناکارہ: عبرانی۔ مرد کی عورت، یا مرد کی بیوی}\n27. کیا آدمی اپنے سینے میں آگ لے سکتا ہے، اور اس کے کپڑے جلائے نہیں جا سکتے؟\n28۔ کیا کوئی گرم انگاروں پر چل سکتا ہے، اور اس کے پاؤں نہ جلیں؟\n29۔ تو جو اپنے پڑوسی کی بیوی کے پاس جاتا ہے؛ جو بھی اسے چھوئے گا وہ بے قصور نہیں ہوگا۔\n30۔ {انسان} چور کو حقیر نہیں کرتے، اگر وہ بھوکے وقت اپنی روح کو تسکین دینے کے لیے چوری کرے؛\n31. لیکن {اگر} وہ مل گیا، تو وہ سات گنا واپس کرے گا؛ وہ اپنے گھر کی ساری دولت دے گا۔\n32۔ {لیکن} جو شخص عورت کے ساتھ کرتا ہے اس میں سمجھ بوجھ نہیں ہوتی: جو یہ کرتا ہے وہ اپنی روح کو تباہ کر دیتا ہے۔ {سمجھ: عبرانی۔ دل}\n33۔ اسے زخم اور بے عزتی ملے گی؛ اور اس کی ملامت مٹائی نہیں جائے گی۔\n34۔ کیونکہ حسد {ہے} انسان کا غصہ: اس لیے وہ انتقام کے دن نہیں چھوڑے گا۔\n35۔ وہ کوئی تاوان قبول نہیں کرے گا؛ نہ ہی وہ مطمئن ہوگا، چاہے تم نے بہت سے تحفے دیے ہوں۔ {وہ کرے گا...: عبرانی۔ وہ کسی بھی تاوان کا چہرہ قبول نہیں کرے گا}","1۔ میرے بیٹے، میرے الفاظ پر قائم رہو، اور میرے احکامات اپنے ساتھ رکھو۔\n2۔ میرے احکامات پر عمل کرو، اور زندہ رہو؛ اور میرا قانون تمہاری آنکھ کا تارا ہے۔\n3۔ انہیں اپنی انگلیوں پر باندھو، اپنے دل کی میز پر لکھو۔\n4۔ حکمت سے کہو، تو میری بہن ہو؛ اور سمجھ بوجھ کو {تیری} رشتہ دار کہو:\n5۔ تاکہ وہ تمہیں اس اجنبی عورت سے روک سکیں، اس اجنبی سے جو اپنی باتوں سے خوشامد کرتا ہے۔\n6۔ کیونکہ میں نے اپنے گھر کی کھڑکی سے اپنے کیسمنٹ سے دیکھا،\n7۔ اور سادہ لوگوں میں، میں نے نوجوانوں میں ایک نوجوان دیکھا، جو سمجھ سے خالی تھا، {نوجوان: عبرانی۔ بیٹے}\n8۔ اپنے کونے کے قریب سڑک سے گزرنا؛ اور وہ اس کے گھر گیا،\n9۔ شام کے وقت، شام میں، سیاہ اور تاریک رات میں: {شام میں: عبرانی۔ دن کی شام میں}\n10۔ اور دیکھو، اس کی ملاقات ایک عورت سے ہوئی جو ایک بدکار عورت کی طرح لباس میں تھی اور دل کی نرم دل تھی۔\n11۔ (وہ شور مچانے والی اور ضدی ہے؛ اس کے پاؤں اس کے گھر میں نہیں رہتے:\n12. اب {کیا و} باہر ہے، اب سڑکوں پر، اور ہر کونے پر انتظار کر رہی ہے۔)\n13۔ تو اس نے اسے پکڑ لیا، اور اسے چوما، {اور} ایک گستاخ چہرے کے ساتھ کہا، {ساتھ...: عبرانی۔ اس نے اپنا چہرہ مضبوط کیا اور کہا}\n14. {میرے پاس صلح کی پیشکشیں ہیں}؛ آج میں نے اپنی قسمیں پوری کر دی ہیں۔ {میرے پاس ہے...: عبرانی۔ امن کی پیشکشیں میرے اوپر ہیں}\n15۔ اسی لیے میں تم سے ملنے آیا، محنت سے تمہارا چہرہ تلاش کرنے کے لیے، اور میں نے تمہیں پا لیا۔\n16. میں نے اپنے بستر کو قالین، کندہ شدہ {کام}، اور مصر کے عمدہ کتان سے سجایا ہے۔\n17۔ میں نے اپنے بستر کو مر، ایلو اور دار چینی سے خوشبو دی ہے۔\n18۔ آؤ، صبح تک محبت سے سیر ہو جائیں: محبتوں سے خود کو تسلی دیں۔\n19۔ نیک انسان {گھر پر نہیں} کے لیے، وہ ایک طویل سفر پر چلا گیا ہے:\n20۔ اس نے پیسے کا تھیلا ساتھ لے کر آیا ہے، {اور} مقررہ دن پر گھر آ جائے گا۔ {ساتھ...: عبوری۔ اس کے ہاتھ میں} {دن...: یا، نیا چاند}\n21۔ اپنی بہت منصفانہ گفتگو سے اس نے اسے مجبور کیا، اپنے ہونٹوں کی خوشامد سے اسے مجبور کیا۔\n22۔ وہ فورا اس کے پیچھے جاتا ہے، جیسے بیل ذبح کے لیے جاتا ہے، یا بیوقوف کی طرح اسٹاک کی اصلاح کے لیے؛ {سیدھا: عبوری۔ اچانک}\n23۔ جب تک کہ ایک تیر اس کے جگر میں نہ لگا؛ جیسے پرندہ جال کی طرف دوڑتا ہے، اور نہیں جانتا کہ یہ اس کی جان کے لیے ہے۔\n24. اب میری بات سنو، اے بچوں، اور میرے منہ کی باتوں پر دھیان دو۔\n25۔ اپنا دل اس کے راستوں کی طرف نہ جھکے، اس کے راستوں میں گمراہ نہ ہو۔\n26۔ کیونکہ اس نے بہت سے زخمیوں کو گرا دیا ہے: ہاں، بہت سے طاقتور لوگ اس کے ہاتھوں مارے گئے ہیں۔\n27. اس کا گھر جہنم کا راستہ ہے، موت کے کمروں کی طرف جاتا ہے۔","1. کیا حکمت نہیں روتی؟ اور سمجھ بوجھ نے اس کی آواز اٹھائی؟\n2۔ وہ اونچی جگہوں کی چوٹی پر کھڑی ہے، راستے کی جگہوں پر۔\n3۔ وہ دروازوں پر، شہر کے داخلے پر، دروازوں پر آنے پر روتی ہے۔\n4۔ اے انسانو، میں تم سے پکار رہا ہوں؛ اور میری آواز انسان کے بیٹوں کے لیے ہے۔\n5. اے سادہ لوگو، حکمت کو سمجھو: اور اے احمقوں، سمجھدار دل کے ہو۔\n6۔ سننا؛ کیونکہ میں عمدہ باتوں کی بات کروں گا؛ اور میرے ہونٹوں کا کھلنا {ہوگا} صحیح چیزیں ہوں گی۔\n7۔ کیونکہ میرا منہ سچ بولے گا؛ اور برائی میرے ہونٹوں کے لیے ایک مکروہ ہے۔ {an...: عبرانی۔ میرے ہونٹوں کی مکروہ پن}\n8۔ میرے منہ کے تمام الفاظ {راستبازی} میں ہیں؛ ان میں کوئی شرارت یا انحراف نہیں ہے۔ {froward: عبرانی۔ ہاروں کے ساتھ}\n9۔ وہ سب اس کے لیے صاف ہیں جو سمجھتا ہے، اور علم پاتے لوگوں کے لیے بھی درست ہیں۔\n10۔ میری تعلیم حاصل کرو، چاندی نہیں؛ اور علم کی بجائے سونے کے انتخاب کے۔\n11۔ کیونکہ حکمت یاقوت سے بہتر ہے؛ اور وہ تمام چیزیں جو چاہتی ہیں، ان کا موازنہ اس سے نہیں کیا جا سکتا۔\n12. میں حکمت کے ساتھ رہتا ہوں، اور ذہین ایجادات کا علم حاصل کرتا ہوں۔ {احتیاط: یا، باریک}\n13. خداوند کا خوف {ہے} کہ میں برائی سے نفرت کروں: غرور، تکبر، اور برائی کا راستہ، اور بد مزاج زبان، مجھے نفرت ہے۔\n14. نصیحت {ہے} میرا ہے، اور صحیح حکمت: میں {سمجھدار} ہوں؛ میرے پاس طاقت ہے۔\n15۔ میرے ذریعے بادشاہ حکومت کرتے ہیں، اور شہزادے انصاف کا حکم دیتے ہیں۔\n16. میرے ذریعے شہزادے حکمرانی کرتے ہیں، اور اشرافیہ، {حتیٰ کہ} زمین کے تمام جج بھی۔\n17. میں ان سے محبت کرتا ہوں جو مجھ سے محبت کرتے ہیں؛ اور جو مجھے جلدی تلاش کریں گے وہ مجھے ڈھونڈ لیں گے۔\n18۔ دولت اور عزت {ہے} میرے پاس ہے؛ {ہاں}، پائیدار دولت اور راستبازی۔\n19۔ میرا پھل سونے سے بہتر ہے، ہاں، عمدہ سونے سے؛ اور میری آمدنی بجائے چوائس سلور۔\n20. میں راستبازی کی راہ میں رہنمائی کرتا ہوں، فیصلے کے راستوں کے درمیان: {رہنمائی کرو: یا، چلتا ہوں}\n21. تاکہ میں اپنے محبت کرنے والوں کو جوہر کا وارث بنا سکوں؛ اور میں ان کے خزانے بھر دوں گا۔\n22. خداوند نے اپنے راستے کے آغاز میں، اس کے پرانے کاموں سے پہلے، مجھے اپنے قبضے میں رکھا۔\n23. مجھے ازل سے ہی قائم کیا گیا تھا، شروع سے یا کبھی زمین سے۔\n24۔ جب {گہرائیاں نہیں تھیں} تو مجھے سامنے لایا گیا؛ جب {وہاں تھے} پانی سے بھرپور چشمے نہیں تھے۔\n25۔ پہاڑوں کے آباد ہونے سے پہلے، پہاڑوں سے پہلے میں سامنے آیا:\n26۔ جبکہ اس نے ابھی تک زمین، کھیت، یا دنیا کی مٹی کا سب سے بلند حصہ نہیں بنایا تھا۔ {کھیتیں: یا، کھلی جگہیں} {سب سے اعلیٰ...: یا، سب سے اہم حصہ}\n27۔ جب اس نے آسمان تیار کیے، میں وہاں تھا: جب اس نے گہرائی کے چہرے پر کمپاس رکھا: {ایک کمپاس: یا، ایک دائرہ}\n28۔ جب اس نے اوپر بادل قائم کیے: جب اس نے گہرے چشموں کو مضبوط کیا:\n29۔ جب اس نے سمندر کو اپنا حکم دیا کہ پانی اس کے حکم پر پورا نہ اترے: جب اس نے زمین کی بنیادیں رکھیں:\n30۔ پھر میں اس کے ساتھ تھا، {جیسا کہ کوئی اس کے ساتھ پلا بڑھا}: اور میں روزانہ {اس کی} خوشی میں رہا، ہمیشہ اس کے سامنے خوش رہتا؛\n31۔ اپنی زمین کے قابل رہائش حصے میں خوشی منانا؛ اور میری خوشیاں انسانوں کے بیٹوں کے ساتھ تھیں۔\n32. اب میری بات سنو، اے بچو، کیونکہ مبارک ہیں وہ لوگ جو میرے راستے سنبھالتے ہیں۔\n33۔ ہدایت سنو، دانا بنو، اور اسے رد نہ کرو۔\n34۔ مبارک ہے وہ آدمی جو مجھے سنتا ہے، روزانہ میرے دروازے پر دیکھتا ہے، میرے دروازوں کے کھمبوں پر انتظار کرتا ہے۔\n35۔ کیونکہ جو بھی مجھے پائے، وہ زندگی پائے گا، اور خداوند کی مہربانی حاصل کرے گا۔ {حاصل کریں: عبوری۔ نکالو}\n36۔ لیکن جو میرے خلاف گناہ کرتا ہے وہ اپنی روح کے ساتھ ظلم کرتا ہے: جو بھی مجھ سے نفرت کرتے ہیں وہ موت کو پسند کرتے ہیں۔","1۔ حکمت نے اس کا گھر تعمیر کیا، اس نے اس کے سات ستون تراشے:\n2۔ اس نے اپنے جانوروں کو مار ڈالا؛ اس نے اپنی شراب ملا لی ہے؛ اس نے اپنی میز بھی سجا دی ہے۔ {اس کے جانور: عبرانی۔ اس کا قتل}\n3۔ اس نے اپنی لڑکیوں کو بھیجا ہے: وہ شہر کی بلند ترین جگہوں پر پکار رہی ہے،\n4۔ جو {سادہ} ہے، وہ یہاں مڑ جائے: {جہاں تک} جو سمجھ چاہتا ہے، وہ اسے کہتی ہے،\n5۔ آؤ، میری روٹی کھاؤ، اور وہ شراب پی لو جو میں نے ملا دی ہے۔\n6۔ بے وقوفوں کو چھوڑ کر جیو؛ اور سمجھ میں رکاوٹ بنیں۔\n7. جو کسی بدکار کو ملامت کرتا ہے وہ خود کو شرمندہ کرتا ہے: اور جو بدکار کو ڈانٹتا ہے وہ خود کو بدنام کرتا ہے۔\n8۔ کسی مذاق کرنے والے کو ملامت نہ کرو، ورنہ وہ تم سے نفرت کرے گا: ایک دانا آدمی کو ڈانٹو، تو وہ تم سے محبت کرے گا۔\n9. ایک دانا کو {ہدایت} دیں، اور وہ اور بھی زیادہ دانا ہو جائے گا: ایک عادل {انسان} کو سکھائیں، اور وہ علم میں اضافہ کرے گا۔\n10. خداوند کا خوف {حکمت کی ابتداء} ہے: اور مقدس {ہے} کا علم سمجھ بوجھ ہے۔\n11۔ کیونکہ میرے ذریعے تمہارے دن بڑھ جائیں گے، اور تمہاری زندگی کے سال بڑھے جائیں گے۔\n12۔ اگر تم دانا ہو، تو اپنے لیے عقلمند ہو گے: لیکن {اگر} تم حقارت کرو گے، تو صرف تم اسے برداشت کرو گے۔\n13. ایک بے وقوف عورت {شور مچاتی} ہے: {وہ} سادہ ہے، اور کچھ نہیں جانتی۔\n14۔ کیونکہ وہ اپنے گھر کے دروازے پر بیٹھی ہے، شہر کی اونچی جگہوں پر ایک نشست پر،\n15. ان مسافروں کو کال کرنا جو سیدھا اپنی راہ پر چلے جاتے ہیں:\n16. جو {سادہ} ہے، اسے یہاں مڑ جائے: اور {جہاں تک} سمجھ چاہتا ہے، وہ اسے کہتی ہے،\n17. چوری شدہ پانی میٹھا ہوتا ہے، اور روٹی {خفیہ طور پر} کھانا خوشگوار ہوتا ہے۔ {کھایا گیا...: عبرانی۔ آف سیکریسیز}\n18۔ لیکن وہ نہیں جانتا کہ مردے وہاں ہیں؛ {اور کہ} اس کے مہمان جہنم کی گہرائیوں میں ہیں۔","1۔ سلیمان کے امثال۔ عقلمند بیٹا خوش باپ بناتا ہے: لیکن نادان بیٹا اپنی ماں کی بھاری پن ہے۔\n2۔ برائی کے خزانے کچھ فائدہ نہیں دیتے: لیکن راستبازی موت سے نجات دیتی ہے۔\n3۔ خداوند نیک لوگوں کی روح کو بھوکا نہیں ہونے دے گا: بلکہ وہ بدکاروں کی چیز کو پھینک دیتا ہے۔ {مادہ...: یا، بدکاروں کی برائی کے لیے}\n4۔ وہ غریب ہو جاتا ہے جو سست ہاتھ سے کام کرتا ہے: لیکن محنتی کا ہاتھ امیر بناتا ہے۔\n5۔ جو گرمیوں میں جمع ہوتا ہے وہ دانا بیٹا ہے: لیکن جو فصل کی فصل میں سوتا ہے وہ شرمندگی کا باعث بنتا ہے۔\n6۔ برکتیں نیک لوگوں کے سر پر ہیں: لیکن بدکاروں کے منہ پر تشدد ہے۔\n7۔ نیک لوگوں کی یاد بابرکت ہے: لیکن بدکاروں کا نام سڑ جائے گا۔\n8۔ دل کے دانا کو احکام ملیں گے: لیکن مذاق کرنے والا بیوقوف گر جائے گا۔ {ایک شرارت...: عبرانی۔ ہونٹوں کا بے وقوف} {گرنا: عبرانی۔ مارا جائے گا}\n9۔ جو سیدھا چلتا ہے وہ یقینا چلتا ہے: لیکن جو اس کے راستے بگاڑتا ہے وہ پہچانا جائے گا۔\n10۔ جو آنکھ مار کر آنکھ مارتا ہے وہ غم لاتا ہے: لیکن ایک مذاق کرنے والا بیوقوف گر جائے گا۔ {زوال: عبرانی۔ مارا جائے گا}\n11۔ نیک انسان کا منہ زندگی کا کنواں ہے: لیکن بدکاروں کے منہ پر تشدد پھیل جاتا ہے۔\n12۔ نفرت جھگڑوں کو جنم دیتی ہے: لیکن محبت تمام گناہوں کو چھپاتی ہے۔\n13۔ جس کے ہونٹوں میں سمجھ بوجھ ہے حکمت ملتی ہے: لیکن ایک چھڑی ہے اس کے لیے جو سمجھ سے خالی ہے۔ {سمجھ سے: عبرانی۔ دل کی}\n14۔ عقلمند {لوگ} علم کو چھوڑ دیتے ہیں: لیکن بے وقوف کا منہ {تباہی کے قریب} ہے۔\n15. امیر آدمی کی دولت {ہے} اس کا مضبوط شہر: غریبوں کی تباہی {ہے} ان کی غربت۔\n16۔ نیک لوگوں کی محنت {زندگی کی طرف}: بدکاروں کا گناہ کا پھل۔\n17. وہ اس طرز زندگی میں ہے جو تعلیم کو برقرار رکھتا ہے: لیکن جو سرزنش سے انکار کرتا ہے وہ غلطی کرتا ہے۔ {ایرتھ: یا، غلطی کا سبب بنتا ہے}\n18۔ جو جھوٹے ہونٹوں سے نفرت چھپاتا ہے، اور جو بہتان کہتا ہے، وہ احمق ہے۔\n19۔ الفاظ کی کثرت میں گناہ کی خواہش نہیں؛ لیکن جو اپنے ہونٹوں سے باز رہتا ہے وہ دانا ہے۔\n20. نیک لوگوں کی زبان {اتنی ہی پسندیدہ} چاندی ہے: بدکاروں کا دل {ہے} کی قدر کم ہے۔\n21۔ نیک لوگوں کے ہونٹ بہت سے لوگوں کو کھلاتے ہیں: لیکن بیوقوف حکمت کی کمی کی وجہ سے مر جاتے ہیں۔ {حکمت کی: عبرانی۔ دل کی}\n22۔ خداوند کی برکت، یہ مالدار بناتی ہے، اور وہ اس میں کوئی غم شامل نہیں کرتا۔\n23۔ شرارت کرنا بے وقوف کے لیے کھیل ہے: لیکن سمجھدار آدمی کے پاس حکمت ہوتی ہے۔\n24۔ بدکاروں کا خوف اس پر آئے گا، لیکن نیک لوگوں کی خواہش پوری ہو جائے گی۔\n25. جیسے طوفان گزرتا ہے، ویسے ہی بدکار بھی نہیں رہتا: بلکہ راستباز ہمیشہ کی بنیاد ہیں۔\n26. جیسے دانتوں کے لیے سرکہ اور آنکھوں کے لیے دھواں ہے، ویسے ہی سست انسان بھی ان کے لیے ہے جو اسے بھیجتے ہیں۔\n27۔ خداوند کا خوف دنوں کو طول دیتا ہے: لیکن بدکاروں کے سال کم ہو جائیں گے۔ {طوالت: عبرانی۔ addeth}\n28. راستبازوں کی امید خوشی ہوگی: لیکن بدکاروں کی امید ختم ہو جائے گی۔\n29۔ خداوند کا راستہ راستبازوں کے لیے طاقت ہے: لیکن بدکاری کرنے والوں کے لیے تباہی {ہوگی}۔\n30۔ نیک کبھی نہیں ہٹائے جائیں گے؛ لیکن بدکار زمین پر نہیں رہیں گے۔\n31۔ عادل کا منہ حکمت لاتا ہے: لیکن ضدی زبان کو کاٹ دیا جائے گا۔\n32. راستبازوں کے ہونٹ جانتے ہیں کہ کیا قابل قبول ہے: لیکن بدکار کا منہ شرارت کہتا ہے۔ {frowardness: عبرانی۔ شرارتیں}","1. جھوٹا توازن خداوند کے لیے مکروہ ہے: لیکن اس کی خوشی ایک مناسب وزن ہے۔ {ایک جعلی...: عبرانی دھوکہ دہی کا توازن} {بس...: عبرانی۔ پرفیکٹ اسٹون}\n2۔ {جب} غرور آتا ہے، تو شرم آتی ہے: لیکن حقیر {ہے} حکمت کے ساتھ۔\n3۔ راست راستوں کی دیانت ان کی رہنمائی کرے گی؛ لیکن مجرموں کی بگاڑ انہیں تباہ کر دے گی۔\n4۔ دولت غصے کے دن فائدہ مند نہیں، بلکہ راستبازی موت سے نجات دیتی ہے۔\n5۔ کامل کی راستبازی اس کا راستہ دکھائے گی؛ لیکن بدکار اپنی برائی سے گر جائے گا۔ {براہ راست: عبرانی Rectify}\n6۔ راستبازوں کی راستبازی انہیں نجات دے گی، لیکن نافرمان اپنی شرارت میں گرفتار ہوں گے۔\n7۔ جب ایک بدکار انسان مر جائے گا، اس کی امید ختم ہو جائے گی: اور ظالموں کی امید ختم ہو جائے گی۔\n8۔ نیک کو مصیبت سے نجات ملتی ہے، اور بدکار اس کی جگہ آتا ہے۔\n9۔ منافق اپنے منہ سے اپنے پڑوسی کو تباہ کر دیتا ہے: لیکن علم کے ذریعے انصاف کو نجات ملے گی۔\n10۔ جب راستبازوں کے ساتھ اچھا ہو تو شہر خوش ہوتا ہے: اور جب بدکار مر جاتے ہیں تو چیخ و پکار ہوتی ہے۔\n11۔ راستوں کی برکت سے شہر بلند ہوتا ہے: لیکن بدکاروں کے منہ سے اسے گرا دیا جاتا ہے۔\n12۔ جو عقل سے خالی ہے وہ اپنے پڑوسی سے نفرت کرتا ہے: لیکن سمجھدار شخص اپنی سکون برقرار رکھتا ہے۔ {void...: عبرانی۔ دل سے محروم}\n13۔ قصہ گو راز ظاہر کرتا ہے: لیکن جو وفادار روح رکھتا ہے وہ معاملہ چھپاتا ہے۔ {ایک قصہ بردار: عبرانی۔ جو چلتا ہے، وہ کہانی سنانے والا ہے}\n14۔ جہاں کوئی وکیل نہ ہو، وہاں لوگ گر جاتے ہیں: لیکن مشیروں کی کثرت میں حفاظت ہوتی ہے۔\n15۔ جو اجنبی کے لیے ضمانت دے گا وہ اس کے لیے عقل مند ہوگا: اور جو ضمانت سے نفرت کرتا ہے وہ یقین رکھتا ہے۔ {سمارٹ: عبوری۔ ٹوٹا ہوا ہوں} {یقینی: عبرانی۔ جو ہاتھ مارتے ہیں}\n16. ایک مہربان عورت عزت برقرار رکھتی ہے: اور مضبوط {مرد} دولت رکھتے ہیں۔\n17۔ رحم دل انسان اپنی جان کے ساتھ بھلائی کرتا ہے: لیکن جو ظالم ہے وہ اپنے جسم کو تکلیف دیتا ہے۔\n18۔ بدکار دھوکہ دہی کا کام کرتا ہے: لیکن جو نیکی پیدا کرتا ہے اس کے لیے یقینی انعام ہوگا۔\n19۔ جیسے راستبازی {زندگی کی طرف بڑھی}: ویسے ہی جو برائی کا پیچھا کرتا ہے {اس کا پیچھا کرتا ہے} اپنی موت تک۔\n20۔ جو دل ضائع کرنے والے ہیں وہ خداوند کے لیے مکروہ ہیں: لیکن {جو اپنے طریقے میں سیدھے ہیں} وہ اس کی خوشی ہیں۔\n21۔ {اگرچہ} ہاتھ میں {ملا} جائے، بدکار بغیر سزا کے نہیں ہوں گے: بلکہ نیک لوگوں کی نسل آزاد ہو جائے گی۔\n22. {جیسے سور کی ناک میں سونے کا جواہر}، {ویسے} ایک خوبصورت عورت بھی ہے جو بے اختیار ہے۔ {بغیر ہے: عبوری۔ چھوڑ کر}\n23. راستبازوں کی خواہش {ہے} صرف بھلائی ہے: {لیکن} بدکاروں کی توقع {ہے} غضب۔\n24. وہ ہے جو بکھرتا ہے، پھر بھی بڑھتا ہے؛ اور {ایسا ہے} جو ملنے سے زیادہ روکتا ہے، لیکن {وہ غربت کی طرف مائل ہوتا ہے}۔\n25۔ فیاض روح موٹی ہو جائے گی: اور جو پانی دے گا وہ خود بھی پانی دے گا۔ {لبرل...: عبوری۔ برکت کی روح}\n26۔ جو اناج روکے گا، لوگ اسے لعنت دیں گے: لیکن جو اسے بیچتا ہے اس کے سر پر برکت ہوگی۔\n27۔ جو محنت سے بھلائی چاہتا ہے وہ فضل حاصل کرتا ہے: لیکن جو شرارت چاہتا ہے، وہ اس کے پاس آئے گا۔\n28۔ جو اپنی دولت پر بھروسہ کرے گا وہ گر جائے گا: لیکن نیک ایک شاخ کی طرح پھلیں گے۔\n29۔ جو اپنے گھر کو پریشان کرے گا وہ ہوا کا وارث ہوگا: اور بیوقوف عقلمندوں کا خادم ہوگا۔\n30۔ راستبازوں کا پھل زندگی کا درخت ہے؛ اور جو روحیں جیتتا ہے وہ دانا ہے۔ {winneth: Hebrew. ٹیکتھ}\n31۔ دیکھو، راستبازوں کو زمین میں سزا ملے گی: اور زیادہ بدکار اور گناہ گار۔","1۔ جو تعلیم سے محبت کرتا ہے وہ علم سے محبت کرتا ہے: لیکن جو ملامت سے نفرت کرتا ہے وہ ظالم ہے۔\n2۔ ایک اچھا انسان خداوند کی عنایت حاصل کرتا ہے: لیکن برے سازشوں والے کو وہ سزا دے گا۔\n3۔ انسان کو برائی سے قائم نہیں کیا جا سکتا: لیکن نیک لوگوں کی جڑ کو ہلکا نہیں دیا جائے گا۔\n4. نیک عورت اپنے شوہر کے لیے تاج ہے: لیکن جو شرمندہ کرتی ہے وہ اس کی ہڈیوں میں سڑنے کی طرح ہے۔\n5. نیک لوگوں کے خیالات {ہیں} درست ہیں: {لیکن} بدکاروں کی نصیحتیں {ہیں} فریب ہیں۔\n6. بدکاروں کے الفاظ خون کے انتظار میں ہیں: لیکن نیک لوگوں کا منہ انہیں نجات دے گا۔\n7۔ بدکاروں کو گرا دیا جاتا ہے، اور وہ نہیں ہوتے: لیکن راستبازوں کا گھر قائم رہے گا۔\n8۔ انسان کو اس کی حکمت کے مطابق سراہا جائے گا؛ لیکن جو دل بگڑا ہوا ہے اسے حقیر سمجھا جائے گا۔ {ایک...: عبرانی دل کی بگاڑ}\n9. {جو حقیر ہے} اور جس کا خادم ہے، {وہ اس سے بہتر ہے جو خود کو عزت دیتا ہے اور روٹی کی کمی رکھتا ہے۔\n10۔ نیک انسان اپنے جانور کی جان کو دیکھتا ہے: لیکن بدکاروں کی نرم رحمتیں ظالم ہوتی ہیں۔ {نرم...: یا، آنتیں}\n11۔ جو اپنی زمین جوتتا ہے وہ روٹی سے مطمئن ہوگا؛ لیکن جو فضول لوگوں کی پیروی کرتا ہے وہ سمجھ سے خالی ہے۔\n12۔ بدکار برائی کے جال کی خواہش رکھتے ہیں {انسان}: لیکن راستبازوں کی جڑ پھل دیتی ہے۔ {نیٹ: یا، قلعہ}\n13۔ بدکار اپنے ہونٹوں کی خلاف ورزی میں پھنس جاتا ہے: لیکن نیک لوگ مصیبت سے نکل آتے ہیں۔ {بدکار...: عبرانی۔ بدکاروں کا جال ہونٹوں کی خلاف ورزی میں ہے}\n14. انسان اپنے منہ کے پھل سے بھلائی سے مطمئن ہو جائے گا: اور انسان کے ہاتھوں کا بدلہ اس کے لیے دیا جائے گا۔\n15۔ بیوقوف کا راستہ اس کی اپنی نظر میں درست ہے: لیکن جو مشورہ سنتا ہے وہ دانا ہے۔\n16۔ ایک احمق کا غصہ اب معلوم ہے: لیکن ایک محتاط انسان شرم کو چھپاتا ہے۔ {فی الحال: عبرانی۔ اس دن}\n17۔ {جو سچ بولتا ہے} وہ راستبازی ظاہر کرتا ہے: لیکن جھوٹا گواہ دھوکہ دہی کرتا ہے۔\n18. ایسی بات ہے جو تلوار کے چھیدنے کی طرح بولتی ہے: لیکن دانا کی زبان صحت مند ہے۔\n19۔ سچائی کا ہونٹ ہمیشہ کے لیے قائم ہوگا: لیکن جھوٹی زبان صرف ایک لمحے کے لیے ہے۔\n20. دھوکہ ان لوگوں کے دل میں ہے جو برائی کا تصور کرتے ہیں: لیکن امن کے مشیروں کے لیے خوشی ہے۔\n21۔ نیک لوگوں کو کوئی برائی نہیں ہوگی، لیکن بدکاروں کو شرارت سے بھر دیا جائے گا۔\n22۔ جھوٹے ہونٹ خداوند کے لیے مکروہ ہیں: لیکن جو واقعی اس کی خوشی کو پیش کرتے ہیں۔\n23۔ ایک عاقل انسان علم چھپاتا ہے: لیکن بے وقوفوں کا دل حماقت کا اعلان کرتا ہے۔\n24۔ محنتی کا ہاتھ حکمرانی کرے گا: لیکن سست لوگ خراج کے تحت ہوں گے۔ {سست: یا، دھوکہ باز}\n25۔ انسان کے دل میں بوجھ اسے جھکا دیتا ہے: لیکن اچھا لفظ اسے خوش کرتا ہے۔\n26۔ نیک اپنے پڑوسی سے زیادہ بہتر ہے: لیکن بدکاروں کا طریقہ انہیں بہکاتا ہے۔ {بہترین: یا، وافر}\n27۔ سست انسان شکار میں جو لیا ہے اسے نہیں بھونتا: لیکن محنتی انسان کی چیز قیمتی ہے۔\n28۔ راستبازی کے راستے میں {ہے} زندگی؛ اور {اس راستے میں} {جہاں سے} کوئی موت نہیں۔","1۔ دانا بیٹا اپنے باپ کی ہدایت سنتا ہے: لیکن مذاق کرنے والا سرزنش نہیں سنتا۔\n2۔ انسان اپنے منہ کے پھل سے اچھا کھائے گا: لیکن مجرموں کی روح تشدد کو کھائے گی۔\n3۔ جو اپنا منہ رکھتا ہے وہ اپنی زندگی کا خیال رکھتا ہے: {لیکن} جو اپنے ہونٹ کھولے گا وہ تباہی کا شکار ہوگا۔\n4۔ سست کی روح چاہتی ہے، اور {ہے} کچھ نہیں: سوائے محنتی کی روح کو موٹا کر دیا جائے گا۔\n5۔ نیک انسان جھوٹ سے نفرت کرتا ہے: لیکن بدکار انسان نفرت انگیز ہے اور شرمندہ ہو جاتا ہے۔\n6۔ راستبازی (جو ہے) راستے میں سیدھا رکھتی ہے: لیکن برائی گناہ گار کو گرا دیتی ہے۔ {گناہگار: عبرانی۔ گناہ}\n7۔ کوئی ہے جو خود کو امیر بناتا ہے، پھر بھی {ہے} کچھ نہیں: {ایسا ہے} جو خود کو غریب بناتا ہے، پھر بھی {ہے} بہت دولت۔\n8۔ انسان کی زندگی کا فدیہ اس کی دولت ہے: لیکن غریب ملامت نہیں سنتا۔\n9۔ راستبازوں کی روشنی خوش ہوتی ہے: لیکن بدکاروں کا چراغ بجھا دیا جائے گا۔ {لیمپ: یا، موم بتی}\n10۔ صرف غرور سے تنازعہ آتا ہے: لیکن اچھی حکمت کے ساتھ۔\n11۔ فضول سود سے حاصل ہونے والی دولت کم ہو جائے گی؛ لیکن جو محنت سے جمع کرے گا وہ بڑھے گا۔ {محنت کے ذریعے: عبرانی۔ ہاتھ سے}\n12۔ امید ملتوی کر دی جاتی ہے دل کو بیمار کر دیتی ہے: لیکن {جب} خواہش آتی ہے، {یہ} زندگی کا درخت ہے۔\n13۔ جو اس کلام سے نفرت کرے گا وہ تباہ ہو جائے گا؛ لیکن جو حکم سے ڈرے گا اسے انعام ملے گا۔ {انعام ملے گا: یا، امن میں ہوگا}\n14. عقلمندوں کا قانون زندگی کا چشمہ ہے، موت کے جال سے نکلنے کے لیے۔\n15۔ اچھی سمجھ بوجھ فضل دیتی ہے: لیکن نافرمان کا راستہ مشکل ہے۔\n16۔ ہر سمجھدار انسان علم سے نمٹتا ہے: لیکن ایک بے وقوف اپنی حماقت کو کھول دیتا ہے۔ {layeth...: عبرانی۔ پھیلتا ہے}\n17۔ ایک بدکار پیغام رساں شرارت میں پڑتا ہے: لیکن وفادار سفیر صحت مند ہے۔ {ایک وفادار...: عبرانی۔ وفاداری کا سفیر}\n18. جو تعلیم دینے سے انکار کرتا ہے اس کے لیے غربت اور شرم ہوگی: لیکن جو ملامت کرتا ہے وہ عزت یافتہ ہوگا۔\n19۔ جو خواہش پوری ہوتی ہے وہ روح کے لیے میٹھی ہوتی ہے: لیکن بیوقوفوں کے لیے برائی سے دور ہونا مکروہ ہے۔\n20۔ جو عقلمندوں کے ساتھ چلتا ہے وہ دانا ہوگا: لیکن احمقوں کا ساتھی تباہ ہو جائے گا۔ {تباہ شدہ: عبرانی۔ ٹوٹا ہوا}\n21۔ برائی گناہ گاروں کا پیچھا کرتی ہے: لیکن نیک نیکی کا بدلہ دیا جائے گا۔\n22۔ ایک اچھا آدمی اپنے بچوں کے بچوں کو وراثت دیتا ہے: اور گناہ گار کی دولت عادلوں کے لیے رکھی جاتی ہے۔\n23۔ غریبوں کی کھیت میں بہت سا کھانا ہے: لیکن وہاں {یعنی} فیصلے کی کمی کی وجہ سے تباہ ہو جاتا ہے۔\n24۔ جو اپنی چھڑی چھوڑتا ہے وہ اپنے بیٹے سے نفرت کرتا ہے؛ لیکن جو اسے چاہتا ہے وہ اسے پہلے ہی سزا دیتا ہے۔\n25۔ نیک اپنی روح کی تسکین کے لیے کھاتا ہے: لیکن بدکاروں کا پیٹ کم ہو جائے گا۔","1۔ ہر دانا عورت اپنا گھر بناتی ہے: لیکن بیوقوف اسے اپنے ہاتھوں سے توڑ دیتا ہے۔\n2۔ جو اپنی راستبازی میں چلتا ہے وہ خداوند سے ڈرتا ہے: لیکن جو اپنے راستوں میں بگڑا ہوا ہے وہ اسے حقیر سمجھتا ہے۔\n3۔ بے وقوف کے منہ میں غرور کی چھڑی ہے: لیکن عقلمندوں کے ہونٹ انہیں محفوظ رکھیں گے۔\n4۔ جہاں کوئی بیل نہیں ہے، وہاں پالنا صاف ہوتا ہے: لیکن بیل کی طاقت سے بہت زیادہ بڑھ جاتا ہے۔\n5۔ وفادار گواہ جھوٹ نہیں بولے گا: لیکن جھوٹا گواہ جھوٹ بولے گا۔\n6۔ ایک طنزیہ حکمت چاہتا ہے، اور {اسے نہیں پاتا}: لیکن علم {سمجھنے والے} کے لیے آسان ہے۔\n7۔ ایک بے وقوف آدمی کی موجودگی سے دور ہو جاؤ، جب تم اس میں علم کے ہونٹ نہیں دیکھتے۔\n8۔ عاقل کی حکمت {ہے} کہ وہ اپنے راستے کو سمجھے: لیکن بیوقوفوں کی حماقت {دھوکہ ہے}۔\n9۔ بیوقوف گناہ کا مذاق اڑاتے ہیں: لیکن راستبازوں میں فضل ہوتا ہے۔\n10۔ دل اپنی تلخی کو جانتا ہے؛ اور ایک اجنبی اس کی خوشی میں مداخلت نہیں کرتا۔ {اس کی اپنی...: عبرانی اس کی روح کی تلخی}\n11۔ بدکاروں کا گھر گرا دیا جائے گا: لیکن راستبازوں کا خیمہ پھلے گا۔\n12. ایک راستہ ہے جو انسان کو درست لگتا ہے، لیکن اس کا اختتام موت کے راستے ہیں۔\n13۔ ہنسی میں بھی دل غمگین ہوتا ہے؛ اور اس خوشی کا اختتام بھاری پن ہے۔\n14۔ دل سے پیچھے ہٹنے والا اپنی راہوں سے بھر جائے گا: اور ایک اچھا آدمی خود سے مطمئن ہوگا۔\n15۔ سادہ ہر لفظ پر یقین کرتا ہے: لیکن محتاط انسان اس کے جانے کو اچھی طرح دیکھتا ہے۔\n16۔ عقلمند انسان ڈرتا ہے اور برائی سے دور ہوتا ہے: لیکن بیوقوف غصے میں آتا ہے اور پراعتماد ہوتا ہے۔\n17۔ {جو ہے} جلد ہی غصے میں آتا ہے وہ بے وقوفی سے معاملہ کرتا ہے: اور بدکار آدمی سے نفرت کی جاتی ہے۔\n18۔ سادہ لوگ حماقت وراثت میں رکھتے ہیں: لیکن محتاط علم سے ملتے ہیں۔\n19۔ برائی کے سامنے جھک جانا؛ اور بدکاروں کو راستبازوں کے دروازے پر۔\n20۔ غریب کو اپنے ہی پڑوسی سے بھی نفرت کی جاتی ہے: لیکن امیر کے بہت سے دوست ہوتے ہیں۔ {امیر...: عبرانی۔ بہت سے امیروں کے عاشق ہیں}\n21۔ جو اپنے پڑوسی سے نفرت کرتا ہے وہ گناہ گار کرتا ہے: لیکن جو غریبوں پر رحم کرتا ہے، وہ خوش نصیب ہے۔\n22۔ کیا وہ برائی کی سازش میں غلطی نہیں کرتے؟ لیکن رحم اور سچائی ان لوگوں کے لیے ہوگی جو نیکی کی منصوبہ بندی کرتے ہیں۔\n23۔ ہر محنت میں منافع ہوتا ہے: لیکن ہونٹوں کی باتیں صرف غربت کی طرف جاتی ہیں۔\n24. عقلمندوں کا تاج ان کی دولت ہے: لیکن بیوقوفوں کی حماقت حماقت ہے۔\n25۔ ایک سچا گواہ جانوں کو نجات دیتا ہے: لیکن دھوکہ باز گواہ جھوٹ بولتا ہے۔\n26۔ خداوند کے خوف میں مضبوط اعتماد ہے: اور اس کے بچے پناہ گاہ پائیں گے۔\n27. خداوند کا خوف زندگی کا چشمہ ہے، موت کے جال سے نکلنے کے لیے۔\n28۔ لوگوں کی کثرت میں بادشاہ کی عزت ہے: لیکن لوگوں کی کمی میں شہزادے کی تباہی ہے۔\n29۔ {جو غصے میں دیر کرتا ہے {وہ بہت سمجھدار ہے} لیکن {جو جذبہ میں جلد بازی کرتا ہے} حماقت کو بلند کرتا ہے۔ {جلدی میں...: عبرانی۔ جذبے کی کمی}\n30۔ صحت مند دل جسمانی زندگی ہے: لیکن ہڈیوں کی سڑن پر حسد کرو۔\n31۔ جو غریبوں پر ظلم کرتا ہے وہ اپنے خالق کو ملامت کرتا ہے؛ لیکن جو اس کی عزت کرتا ہے وہ غریبوں پر رحم کرتا ہے۔\n32. بدکار اپنی برائی میں دور ہو جاتا ہے: لیکن نیک اپنی موت میں امید رکھتے ہیں۔\n33۔ حکمت اس کے دل میں ہے جو سمجھدار ہے: لیکن جو کچھ ہے وہ بے وقوفوں کے درمیان ظاہر ہوتا ہے۔\n34۔ راستبازی قوم کو بلند کرتی ہے: لیکن گناہ کسی بھی قوم کے لیے ملامت ہے۔ {کسی کو...: عبرانی قوموں کے لیے}\n35۔ بادشاہ کی مہربانی ایک دانا خادم کے لیے ہے: لیکن اس کا غضب اس پر ہے جو شرمندگی کا باعث بنتا ہے۔","1۔ نرم جواب غصے کو دور کر دیتا ہے: لیکن سخت الفاظ غصے کو ابھارتے ہیں۔\n2۔ دانا کی زبان علم کو صحیح طریقے سے استعمال کرتی ہے: لیکن بے وقوفوں کا منہ حماقت نکالتا ہے۔ {poureth: عبرانی۔ بیلچتھ، یا، ببلتھ}\n3. خداوند کی آنکھیں ہر جگہ ہیں، برائی اور نیکی کو دیکھ رہی ہیں۔\n4. صحت مند زبان زندگی کا درخت ہے: لیکن اس میں انحراف روح میں دراڑ ہے۔ {ایک صحت مند...: عبرانی۔ زبان کی شفا}\n5۔ بیوقوف اپنے باپ کی ہدایت کو حقیر سمجھتا ہے؛ لیکن جو ملامت کرتا ہے وہ دانشمند ہے۔\n6۔ راستبازوں کے گھر میں بہت خزانہ ہے: لیکن بدکاروں کی آمدنی میں مصیبت ہے۔\n7۔ دانا کے ہونٹ علم کو پھیلاتے ہیں: لیکن بے وقوف کا دل ایسا نہیں کرتا۔\n8. بدکاروں کی قربانی خداوند کے لیے مکروہ ہے: لیکن راستباز کی دعا اس کی خوشی ہے۔\n9۔ بدکاروں کا راستہ خداوند کے لیے مکروہ ہے: لیکن وہ اس سے محبت کرتا ہے جو راستبازی کے بعد چلتا ہے۔\n10۔ جو راستہ چھوڑ کر جاتا ہے اس کے لیے اصلاح دردناک ہے: اور جو ملامت سے نفرت کرتا ہے وہ مر جائے گا۔ {تصحیح: یا، ہدایت}\n11. جہنم اور تباہی خداوند کے سامنے ہیں: انسانوں کے بچوں کے دلوں سے کہیں زیادہ؟\n12۔ مذاق کرنے والا اس سے محبت نہیں کرتا جو اسے ملامت کرے: نہ ہی وہ عقلمندوں کے پاس جائے گا۔\n13۔ خوش دل خوشگوار چہرہ بناتا ہے: لیکن دل کے غم سے روح ٹوٹ جاتی ہے۔\n14۔ جس کا دل سمجھدار ہے وہ علم چاہتا ہے: لیکن بیوقوفوں کا منہ حماقت پر پلتا ہے۔\n15۔ مصیبت زدہ کے تمام دن برے ہیں: لیکن جو خوش دل ہے اس کے لیے مسلسل دعوت ہوتی ہے۔\n16۔ خداوند کے خوف کے ساتھ زیادہ خزانے اور مصیبت سے بہتر ہے۔\n17. جہاں محبت ہے وہاں جڑی بوٹیوں کا کھانا بہتر ہے، بجائے اس کے کہ اس کے ساتھ رکا ہوا بیل اور نفرت ہو۔\n18۔ غصہ کرنے والا آدمی فساد کو جنم دیتا ہے: لیکن جو غصہ کرنے میں دیر کرتا ہے وہ جھگڑا کم کرتا ہے۔\n19۔ سست لوگوں کا راستہ کانٹوں کی باڑ کی طرح ہے: لیکن راستبازوں کا راستہ واضح ہے۔ {بنایا گیا ہے...: عبرانی۔ ایک کاز کے طور پر پالا جاتا ہے}\n20۔ دانا بیٹا خوش باپ بناتا ہے: لیکن بیوقوف اپنی ماں سے نفرت کرتا ہے۔\n21۔ حماقت {جو عقل سے محروم ہے} کے لیے خوشی ہے: لیکن سمجھدار آدمی سیدھا چلتا ہے۔ {بے سہاری...: عبدی۔ دل کا خالی}\n22۔ بغیر وکیل کے مقاصد مایوس ہوتے ہیں: لیکن مشیروں کی کثرت میں وہ قائم ہو جاتے ہیں۔\n23۔ انسان اپنے منہ کے جواب سے خوشی پاتا ہے: اور ایک لفظ جو وقت پر کہا جائے، کتنا اچھا ہے! {وجہ سے...: عبرانی۔ اس کا سیزن}\n24. زندگی کا طریقہ اوپر عقلمند کے لیے ہے، تاکہ وہ نیچے جہنم سے نکل سکے۔\n25. خداوند مغرور کے گھر کو تباہ کرے گا: لیکن وہ بیوہ کی سرحد قائم کرے گا۔\n26. بدکاروں کے خیالات خداوند کے لیے مکروہ ہیں: لیکن پاک کے الفاظ خوشگوار الفاظ ہیں۔ {خوشگوار...: عبرانی۔ خوشگوار الفاظ}\n27۔ جو فائدے کا لالچی ہے وہ اپنے گھر کو نقصان پہنچاتا ہے؛ لیکن جو تحفوں سے نفرت کرتا ہے وہ زندہ رہے گا۔\n28۔ راستبازوں کا دل جواب دینے کی کوشش کرتا ہے: لیکن بدکاروں کا منہ برے الفاظ بہاتا ہے۔\n29۔ خداوند {ہے} بدکاروں سے دور ہے: لیکن وہ راستبازوں کی دعا سنتا ہے۔\n30۔ آنکھوں کی روشنی دل کو خوش کرتی ہے: {اور} اچھی خبر ہڈیوں کو موٹا کر دیتی ہے۔\n31۔ جو کان زندگی کی ملامت سنتا ہے وہ داناؤں کے درمیان رہتا ہے۔\n32. جو تعلیم سے انکار کرتا ہے وہ اپنی روح سے نفرت کرتا ہے؛ لیکن جو سنتا ہے وہ سمجھ بوجھ حاصل کرتا ہے۔ {ہدایت: یا، تصحیح} {سنو: یا، اطاعت کرو} {getetteh...: عبرانی۔ دل رکھتی ہے}\n33. خداوند کا خوف {ہے} حکمت کی تعلیم؛ اور عزت کے سامنے عاجزی ہے۔","1۔ انسان میں دل کی تیاریاں، اور زبان کا جواب، {ہے} خداوند کی طرف سے۔ {تیاریاں: یا، تلف کرنا}\n2۔ انسان کی تمام راہیں اس کی اپنی نظر میں صاف ہیں؛ لیکن خداوند روحوں کو تولتا ہے۔\n3۔ اپنے اعمال خداوند کے سپرد کرو، اور تمہارے خیالات قائم ہو جائیں گے۔ {کمٹ: عبرانی۔ رول}\n4۔ خداوند نے سب کچھ اپنے لیے بنایا ہے: ہاں، یہاں تک کہ برے لوگوں کو بھی برائی کے دن کے لیے۔\n5. ہر وہ شخص جو دل میں مغرور ہو {وہ خداوند کے لیے مکروہ ہے: {چاہے} ہاتھ {جوڑ} ہو، وہ بے سزا نہیں ہوگا۔ {بغیر سزا کے: عبرانی۔ بے گناہ سمجھا جاتا ہے}\n6۔ رحمت اور سچائی سے بدکاری پاک ہوتی ہے: اور خداوند کے خوف سے برائی سے دور ہوتے ہیں۔\n7۔ جب انسان کے طریقے خداوند کو پسند آتے ہیں، تو وہ اپنے دشمنوں کو بھی اپنے ساتھ امن میں لانے پر مجبور کرتا ہے۔\n8. راستبازی کے ساتھ تھوڑا سا بہتر ہے بجائے اس کے کہ بغیر حق کے بڑی آمدنی حاصل ہو۔\n9۔ انسان کا دل اپنا راستہ بناتا ہے: لیکن خداوند اس کے قدم ہدایات کرتا ہے۔\n10۔ ایک الہی جملہ {ہے} بادشاہ کے ہونٹوں پر: اس کا منہ فیصلے میں خلاف ورزی نہیں کرتا۔ {ایک الہی...: عبرانی۔ فال گیری}\n11۔ ایک منصفانہ وزن اور توازن {ہیں} خداوند کا: تھیلے کے تمام وزن {ہیں} اس کا کام۔ {وزن: عبرانی۔ دی اسٹونز}\n12. {بادشاہوں کے لیے برائی کرنا} مکروہ ہے: کیونکہ تخت راستبازی سے قائم ہوتا ہے۔\n13۔ نیک ہونٹ بادشاہوں کی خوشی ہیں؛ اور وہ اس سے محبت کرتے ہیں جو صحیح بولتا ہے۔\n14. بادشاہ کا غضب موت کے پیغامبر کی طرح ہے: لیکن ایک دانا اسے مطمئن کرے گا۔\n15۔ بادشاہ کے چہرے کی روشنی میں {ہے} زندگی؛ اور اس کی عنایت {ہے} اس آخری بارش کے بادل کی طرح۔\n16. سونے سے دانائی حاصل کرنا کتنا بہتر ہے! اور سمجھ بوجھ حاصل کرنا، چاندی کے بجائے منتخب ہونے کے بجائے!\n17۔ راستوں کا راستہ برائی سے دور ہونا ہے: جو اپنی راہ پر قائم رہتا ہے وہ اپنی روح کو محفوظ رکھتا ہے۔\n18۔ تباہی سے پہلے غرور {جاتا ہے}، اور زوال سے پہلے مغرور روح۔\n19۔ بہتر ہے کہ آپ عاجز لوگوں کے ساتھ عاجز رہیں، بجائے اس کے کہ مال کو مغرور لوگوں کے ساتھ تقسیم کریں۔\n20۔ جو کسی معاملے کو دانشمندی سے سنبھالے گا، اسے بھلائی ملے گی؛ اور جو خداوند پر بھروسہ کرے گا، وہ خوش نصیب ہے۔ {ہینڈلتھ...: یا، کسی معاملے کو سمجھتا ہے}\n21۔ دل کے دانا کو محتاط کہا جائے گا: اور ہونٹوں کی مٹھاس علم میں اضافہ کرتی ہے۔\n22۔ سمجھ بوجھ زندگی کا چشمہ ہے اس کے لیے جس کے پاس یہ ہے: لیکن بے وقوفوں کی تعلیم حماقت ہے۔\n23۔ دانا کا دل اس کے منہ کو سکھاتا ہے، اور اس کے ہونٹوں میں علم شامل کرتا ہے۔ {ٹیچتھ: عبرانی۔ میکتھ وائز}\n24۔ خوشگوار الفاظ شہد کی چھتے کی طرح ہیں، روح کے لیے میٹھے اور ہڈیوں کو صحت بخش۔\n25. ایک راستہ ہے جو انسان کو درست لگتا ہے، لیکن اس کا اختتام موت کے راستے ہیں۔\n26۔ جو محنت کرتا ہے وہ اپنے لیے محنت کرتا ہے؛ کیونکہ اس کا منہ اس سے اسے طلب کرتا ہے۔ {وہ...: عبرانی۔ اس کی روح جو} {خواہش...: عبرانی اس کے سامنے جھک جاؤ}\n27۔ ایک بے دین آدمی برائی کو کھودتا ہے: اور اس کے ہونٹوں میں جلتی ہوئی آگ کی طرح ہے۔ {این...: عبرانی۔ بیلیال کا آدمی}\n28۔ ایک آوارہ آدمی فساد پھیلاتا ہے: اور سرگوشی کرنے والا سردار دوستوں کو جدا کرتا ہے۔ {سوئیتھ: عبرانی۔ بھیجو}\n29۔ ایک پرتشدد آدمی اپنے پڑوسی کو بہکاتا ہے، اور اسے اس راہ پر لے جاتا ہے جو کہ اچھا نہیں ہے۔\n30۔ وہ اپنی آنکھیں بند کر کے شرارتی منصوبے بناتا ہے: اپنے ہونٹوں کو حرکت دے کر برائی کو آگے لے آتا ہے۔\n31۔ بوڑھا سر {ہے} جلال کا تاج ہے، {اگر} یہ راستبازی کے راستے میں پایا جائے۔\n32. {جو غصہ کرنے میں سست ہے} طاقتور سے بہتر ہے؛ اور جو اپنی روح پر حکمرانی کرتا ہے، وہ جو شہر لیتا ہے۔\n33۔ لاٹ گود میں ڈالا جاتا ہے؛ لیکن اس کا پورا انتظام خداوند کا ہے۔","1. ایک خشک نوالہ اور اس کے ساتھ خاموشی بہتر ہے، بجائے اس کے کہ ایک ایسا گھر جو قربانیوں سے بھرا ہو اور جدوجہد کرے۔ {قربانیاں: یا، خدا کی قسم}\n2۔ ایک عقلمند خادم اس بیٹے پر حکمرانی کرے گا جو شرمندگی کا باعث بنتا ہے، اور بھائیوں کے درمیان وراثت کا کچھ حصہ حاصل کرے گا۔\n3۔ فائننگ برتن چاندی کے لیے ہے، اور بھٹی سونے کے لیے: لیکن خداوند دلوں کو آزماتا ہے۔\n4۔ ایک بدکار شخص جھوٹے ہونٹوں کی سنتا ہے؛ {اور} جھوٹا شرارتی زبان کو سنتا ہے۔\n5۔ جو غریب کا مذاق اڑاتا ہے وہ اپنے خالق کو ملامت کرتا ہے: {اور} جو مصیبت پر خوش ہوتا ہے وہ بغیر سزا کے نہیں بچے گا۔ {بغیر سزا کے: عبرانی۔ بے گناہ سمجھا جاتا ہے}\n6۔ بچوں کے بچے بوڑھوں کا تاج ہیں؛ اور بچوں کی شان ان کے والد ہیں۔\n7۔ عمدہ گفتگو بے وقوف نہیں بنتی، جھوٹے ہونٹ شہزادہ تو دور کی بات ہے۔ {بہترین...: عبرانی۔ ایک شاندار لہجہ} {جھوٹ...: عبرانی۔ جھوٹ بولنے کا ہونٹ}\n8۔ تحفہ {ہے} اس کی نظر میں قیمتی پتھر کی مانند ہے جس کے پاس ہے: جہاں بھی وہ جائے، وہ خوشحال ہے۔ {ایک قیمتی...: عبرانی۔ فضل کا پتھر}\n9۔ جو کوئی گناہ چھپاتا ہے وہ محبت چاہتا ہے؛ لیکن جو کوئی بات دہراتا ہے وہ {بہت} دوست الگ کرتا ہے۔ {seeketh: or, procureth}\n10۔ سرزنش ایک عقلمند آدمی میں سو پٹیوں سے زیادہ داخل ہوتی ہے بجائے ایک بے وقوف کے۔ {داخل ہوتا ہے...: یا، ایک عقلمند آدمی سے بھی زیادہ، بجائے اس کے کہ کسی بے وقوف کو سو بار مارے}\n11۔ ایک برا {انسان} صرف بغاوت چاہتا ہے: اس لیے اس کے خلاف ایک ظالم پیغام بھیجا جائے گا۔\n12. ایک ریچھ جو اپنے بچوں سے محروم ہو جائے، ایک مرد سے ملے، نہ کہ ایک بے وقوف جو اپنی حماقت میں ہو۔\n13۔ جو برائی کو اچھائی کے بدلے انعام دیتا ہے، وہ برائی اپنے گھر سے نہیں جائے گی۔\n14. جھگڑے کی ابتدا {ویسی ہی ہے} جب کوئی پانی چھوڑ دیتا ہے: لہٰذا بحث کو چھوڑ دو، اس سے پہلے کہ اس میں مداخلت کی جائے۔\n15. جو بدکاروں کو راستباز بناتا ہے، اور جو نیک کو سزا دیتا ہے، وہ دونوں خداوند کے لیے مکروہ ہیں۔\n16. کیوں ایک بے وقوف کے ہاتھ میں حکمت حاصل کرنے کی قیمت ہے، جب کہ وہ اس کے لیے دل نہیں رکھتا؟\n17۔ ایک دوست ہمیشہ محبت کرتا ہے، اور ایک بھائی مشکلات کے لیے پیدا ہوتا ہے۔\n18۔ سمجھ سے خالی آدمی ہاتھ مارتا ہے، {اور} اپنے دوست کی موجودگی میں یقین دلاتا ہے۔ {سمجھ: عبرانی۔ دل}\n19۔ وہ گناہ سے محبت کرتا ہے جو لڑائی سے محبت کرتی ہے: {اور} جو اپنے دروازے کو بلند کرتا ہے وہ تباہی چاہتا ہے۔\n20۔ جس کا دل بگڑتا ہے اسے کوئی بھلائی نہیں ملتی اور جس کی زبان بگڑی ہوئی ہو وہ شرارت میں گر جاتا ہے۔ {جس کے پاس ایک آوارہ ہے...: عبرانی۔ دل کا آوارہ}\n21. جو احمق پیدا کرتا ہے وہ اپنے غم میں مبتلا کرتا ہے: اور بیوقوف کا باپ خوشی نہیں رکھتا۔\n22۔ خوش دل بھلائی کرتا ہے جیسے دوا ہو، لیکن ٹوٹا ہوا روح ہڈیوں کو خشک کر دیتا ہے۔ {like: or, to}\n23. ایک بدکار {انسان} اپنے سینے سے تحفہ نکال کر فیصلے کے راستے بگاڑتا ہے۔\n24۔ حکمت {ہے} اس کے سامنے جو سمجھدار ہے؛ لیکن ایک بے وقوف کی آنکھیں زمین کے کناروں میں ہیں۔\n25۔ ایک بے وقوف بیٹا اپنے والد کے لیے غم ہے، اور اس کے لیے تلخی جو اسے جنم دیتی ہے۔\n26. انصاف کرنے والوں کو سزا دینے کے لیے، نہ ہی شہزادوں کو انصاف کے لیے مارنے کے لیے۔\n27. جس کے پاس علم ہے وہ اپنے الفاظ سے بچتا ہے: {اور} سمجھدار انسان بہترین روح کا حامل ہے۔ {an...: یا، ایک کول}\n28۔ حتیٰ کہ بیوقوف بھی، جب وہ خاموش رہتا ہے، اسے دانا سمجھا جاتا ہے: {اور} جو اپنے ہونٹ بند کرتا ہے {اسے سمجھدار سمجھا جاتا ہے}۔","1۔ خواہش کے ذریعے ایک آدمی، جو خود کو الگ کر چکا ہو، تمام حکمت کی تلاش کرتا ہے {اور} اس میں مداخلت کرتا ہے۔ {ذریعے...: یا، جو خود کو الگ کرتا ہے وہ اپنی خواہش کے مطابق تلاش کرتا ہے، اور ہر کام میں مداخلت کرتا ہے}\n2۔ ایک بیوقوف کو سمجھنے میں خوشی نہیں، سوائے اس کے کہ اس کا دل خود کو دریافت کرے۔\n3۔ جب بدکار آتا ہے، {تو} حقارت بھی آتی ہے، اور ذلت آمیز ملامت کے ساتھ۔\n4۔ انسان کے منہ کے الفاظ {گہرے پانیوں کی طرح} ہیں، {اور} حکمت کا چشمہ {بہتے ہوئے ندی کی طرح}۔\n5. {یہ اچھا نہیں کہ بدکار شخص کو قبول کیا جائے، اور انصاف کے ذریعے راستبازوں کو شکست دی جائے۔\n6. ایک بے وقوف کے ہونٹ لڑائی میں آتے ہیں، اور اس کا منہ چھونے کے لیے پکارتا ہے۔\n7۔ ایک بے وقوف کا منہ اس کی تباہی ہے، اور اس کے ہونٹ اس کی روح کا جال ہیں۔\n8۔ کہانی سنانے والے کے الفاظ زخموں کی طرح ہوتے ہیں، اور وہ پیٹ کے اندرونی حصوں تک اتر جاتے ہیں۔ {قصہ بردار: یا، سرگوشی} {زخموں کے طور پر: یا، جیسے آدمی زخمی ہوتے ہیں} {زیادہ تر...: عبرانی۔ چیمبرز}\n9۔ جو بھی اپنے کام میں سست ہے، وہ اس کا بھائی ہے جو بڑا فضول خرچی ہے۔\n10. خداوند کا نام {ہے} ایک مضبوط مینار ہے: نیک اس میں دوڑتا ہے اور محفوظ ہے۔ {محفوظ: عببرانی۔ اوپر رکھو}\n11۔ امیر آدمی کی دولت اس کا مضبوط شہر ہے، اور اس کے اپنے غرور میں ایک بلند دیوار کی طرح۔\n12۔ تباہی سے پہلے انسان کا دل مغرور ہوتا ہے، اور عزت سے پہلے عاجزی ہوتی ہے۔\n13۔ جو کوئی سوال سننے سے پہلے جواب دیتا ہے، وہ اس کے لیے حماقت اور شرم ہے۔ {جواب دیتا ہے...: عبرانی۔ ایک لفظ واپس کرتا ہے}\n14۔ انسان کی روح اس کی کمزوری کو سہارا دیتی ہے؛ لیکن ایک زخمی روح جو برداشت کر سکتی ہے؟\n15۔ دانشمندانہ علم کا دل؛ اور دانا کا کان علم کی تلاش میں ہے۔\n16۔ انسان کا تحفہ اس کے لیے جگہ بناتا ہے، اور اسے عظیم لوگوں کے سامنے لے آتا ہے۔\n17۔ {جو ہے} اپنے مقصد میں سب سے پہلے {منصف نظر آتا ہے}؛ لیکن اس کا پڑوسی آتا ہے اور اسے تلاش کرتا ہے۔\n18۔ قرعہ تنازعات کو ختم کر دیتا ہے، اور طاقتوروں کے درمیان تقسیم ہو جاتا ہے۔\n19۔ بھائی جو ناراض ہو جائے {اسے جیتنا مشکل ہے} بنسبت ایک مضبوط شہر کے: اور {ان کے} تنازعات {ہیں} قلعے کی سلاخوں کی طرح۔\n20۔ انسان کا پیٹ اس کے منہ کے پھل سے مطمئن ہوگا؛ {اور} اس کے ہونٹوں کے بڑھنے سے وہ بھر جائے گا۔\n21. موت اور زندگی زبان کی طاقت میں ہیں: اور جو اسے پسند کرتے ہیں وہ اس کا پھل کھائیں گے۔\n22۔ {جو بھی} بیوی پائے، وہ اچھی {چیز} پائے گا، اور خداوند کی مہربانی حاصل کرے گا۔\n23۔ غریب درخواستیں استعمال کرتا ہے؛ لیکن امیر لوگ سختی سے جواب دیتے ہیں۔\n24۔ جس آدمی کے دوست ہوں اسے خود کو دوستانہ دکھانا چاہیے: اور ایک دوست ہے جو بھائی سے زیادہ قریب رہتا ہے۔","1. وہ غریب جو اپنی دیانتداری میں چلتا ہے، بہتر ہے بجائے اس کے کہ وہ جو اپنے لبوں میں بگڑا ہوا ہے اور بیوقوف ہے۔\n2. اور یہ کہ، {کہ} روح {بے علم} ہو، {یہ اچھی نہیں}؛ اور جو اپنے قدموں سے جلدی کرتا ہے وہ گناہ کرتا ہے۔\n3۔ انسان کی حماقت اس کے راستے کو بگاڑ دیتی ہے: اور اس کا دل خداوند کے خلاف پریشان ہوتا ہے۔\n4۔ دولت بہت سے دوست بناتی ہے؛ لیکن غریب اپنے پڑوسی سے جدا ہو جاتا ہے۔\n5۔ جھوٹا گواہ بغیر سزا کے نہیں ملے گا، اور جو جھوٹ بولے گا وہ بچ نہیں سکتا۔ {بغیر سزا کے: عبرانی۔ بے گناہ سمجھا جاتا ہے}\n6۔ بہت سے لوگ شہزادے کی عنایت مانگیں گے: اور ہر آدمی اس کا دوست ہے جو تحفے دیتا ہے۔ {وہ...: عبرانی۔ ایک تحفے والا آدمی}\n7۔ غریبوں کے تمام بھائی اس سے نفرت کرتے ہیں: اس کے دوست اس سے اور کتنے دور جاتے ہیں؟ وہ الفاظ کے ساتھ {ان کا پیچھا کرتا ہے}، {پھر بھی} وہ {اسے چاہتے ہیں}۔\n8۔ جو حکمت حاصل کرتا ہے وہ اپنی روح سے محبت کرتا ہے: جو سمجھ بوجھ رکھتا ہے وہ بھلائی پائے گا۔ {حکمت: عبرانی۔ ایک دل}\n9۔ جھوٹا گواہ بغیر سزا کے نہیں ملے گا، اور جو جھوٹ بولے گا وہ فنا ہو جائے گا۔\n10۔ بے وقوف کے لیے خوشی مناسب نہیں؛ اور خاص طور پر کہ ایک خادم شہزادوں پر حکمرانی کرے۔\n11۔ انسان کی صوابدید اپنے غصے کو مؤخر کرتی ہے؛ اور یہ اس کی شان ہے کہ وہ کسی گناہ کو نظر انداز کر دے۔ {صوابدید: یا، احتیاط}\n12. بادشاہ کا غضب {ہے} شیر کی دہاڑ کی طرح؛ لیکن اس کی مہربانی گھاس پر شبنم کی طرح ہے۔\n13۔ ایک بے وقوف بیٹا {ہے} اپنے والد کی آفت: اور بیوی کے جھگڑے {} مسلسل زوال ہیں۔\n14۔ گھر اور دولت {ہیں} باپ کی وراثت: اور ایک محتاط بیوی {ہے} خداوند کی طرف سے۔\n15۔ سستی گہری نیند میں ڈال دیتی ہے؛ اور ایک سست روح بھوک کا شکار ہوگی۔\n16۔ جو حکم کی پاسداری کرتا ہے، وہ اپنی جان کا خیال رکھتا ہے؛ {لیکن} جو اس کے طریقے سے نفرت کرے گا وہ مر جائے گا۔\n17۔ جو غریبوں پر رحم کرتا ہے وہ خداوند کو قرض دیتا ہے؛ اور جو کچھ اس نے دیا ہے وہ اسے واپس دے گا۔ {وہ جو...: یا، اس کا عمل}\n18۔ جب تک امید ہے اپنے بیٹے کو سزا دے، اور اپنی روح کو اس کی رونے کے لیے معاف نہ کرے۔ {لیے...: یا، اس کی تباہی کے لیے: یا، اسے مرنے کے لیے}\n19۔ شدید غصے والا آدمی سزا پائے گا: کیونکہ اگر تم اسے بچا لو، تو تمہیں دوبارہ کرنا ہوگا۔ {do: عبوری۔ add}\n20۔ نصیحت سنو اور تعلیم حاصل کرو، تاکہ تم اپنے آخری انجام میں دانا بن سکو۔\n21۔ {انسان کے دل میں کئی آلات ہوتے ہیں}؛ تاہم خداوند کی نصیحت برقرار رہے گی۔\n22. انسان کی خواہش اس کی مہربانی ہے: اور غریب آدمی جھوٹے سے بہتر ہے۔\n23۔ خداوند کا خوف {زندگی کی طرف بڑھا}: اور {جس کے پاس ہے} ہمیشہ مطمئن رہے گا؛ اسے برائی کا سامنا نہیں کرنا چاہیے۔\n24۔ ایک سست آدمی اپنا ہاتھ {اپنی} کے سینے میں چھپاتا ہے، اور اسے دوبارہ منہ تک نہیں لے جاتا۔\n25۔ ایک بدتمیز کو مارو، تو سادہ خبردار ہوں گے: اور جو سمجھدار ہے اسے ملامت کرے گا، {اور} وہ علم کو سمجھ جائے گا۔ {خبردار: عبرانی۔ ہوشیار ہوگا}\n26. جو اپنے باپ کو ضائع کرتا ہے، اور اپنی ماں کو بھگا دیتا ہے، وہ ایسا بیٹا ہے جو شرمندگی کا باعث بنتا ہے اور ملامت لاتا ہے۔\n27۔ میرے بیٹے، اس ہدایت کو سننا بند کرو {جو علم کے الفاظ سے غلطی کا باعث بنتی ہے۔\n28۔ ایک بے دین گواہ فیصلے کو حقیر سمجھتا ہے: اور بدکار کا منہ گناہوں کو نگلتا ہے۔ {این...: عبرانی۔ بلیال کا گواہ\n29۔ فیصلے طنزیہ افراد کے لیے تیار کیے جاتے ہیں، اور بے وقوفوں کی پیٹھ کے لیے دھاریاں ہیں۔","1۔ شراب ایک مذاق اڑانے والی ہے، تیز مشروب غصہ ہے: اور جو اس سے دھوکہ کھاتا ہے وہ عقلمند نہیں ہوتا۔\n2. بادشاہ کا خوف شیر کی دہاڑ کی طرح ہے: {جو بھی} اسے غصہ دلاتا ہے وہ اپنی روح کے خلاف گناہ کرتا ہے۔\n3. یہ ایک شخص کے لیے اعزاز ہے کہ وہ جھگڑے سے باز رہے: لیکن ہر بیوقوف مداخلت کرے گا۔\n4۔ سست شخص سردی کی وجہ سے ہل نہیں چلاتا؛ {لہٰذا} وہ فصل کی فصل میں بھیک مانگے گا، اور {کچھ نہیں ہوگا}۔ {سردی: یا، سردی}\n5۔ انسان کے دل میں مشورہ گہرے پانی کی مانند ہے؛ لیکن سمجھدار آدمی اسے نکال لے گا۔\n6۔ زیادہ تر لوگ ہر ایک کو اس کی اپنی بھلائی کا اعلان کریں گے: لیکن ایک وفادار آدمی جو پا سکتا ہے؟ {نیکی: یا، انعام}\n7. عادل {انسان} اپنی دیانتداری میں چلتا ہے: اس کے بچے {} اس کے بعد برکت یافتہ ہیں۔\n8۔ جو بادشاہ تخت انصاف پر بیٹھا ہو، اپنی آنکھوں سے تمام برائی کو دور کر دیتا ہے۔\n9۔ کون کہہ سکتا ہے کہ میں نے اپنا دل صاف کر دیا ہے، میں اپنے گناہ سے پاک ہوں؟\n10. ڈائیورز وزن، {اور} ڈائیورز ناپیں، دونوں {ہیں} خداوند کے لیے یکساں مکروہ ہیں۔ {ڈائیورز وزن: عبرانی۔ ایک پتھر اور ایک پتھر} {متنوع پیمائش: عبرانی۔ ایک ایفاہ اور ایک ایفاہ}\n11. یہاں تک کہ بچہ بھی اپنے اعمال سے جانا جاتا ہے، چاہے اس کا کام {پاک} ہو، اور کیا وہ درست ہے۔\n12۔ سننے والا کان، اور دیکھنے والی آنکھ، خداوند نے دونوں کو برابر بنایا ہے۔\n13۔ نیند سے محبت نہ کرو، ورنہ غربت میں آ جاؤ گے؛ اپنی آنکھیں کھولو، {اور} تم روٹی سے مطمئن ہو جاؤ گے۔\n14. {یہ کچھ نہیں}، {یہ کچھ نہیں}، خریدار کہتا ہے: لیکن جب وہ اپنے راستے سے چلا جاتا ہے، تب وہ فخر کرتا ہے۔\n15۔ سونا ہے، اور بہت سارے یاقوت، لیکن علم کے ہونٹ ایک قیمتی جواہر ہیں۔\n16۔ اس کا وہ لباس لے لو جو کسی اجنبی کے لیے ضمانت ہے: اور اس سے ایک اجنبی عورت کے لیے گروی رکھو۔\n17. دھوکہ دہی کی روٹی {مردوں کے لیے میٹھی} ہے؛ لیکن اس کے بعد اس کا منہ بجری سے بھر جائے گا۔ {دھوکہ: عبوری۔ جھوٹ، یا، جھوٹ}\n18۔ {ہر مقصد} مشورے سے طے کیا جاتا ہے: اور اچھی نصیحت کے ساتھ جنگ شروع کرو۔\n19۔ جو کہانی سنانے والے کے طور پر گھومتا ہے وہ راز ظاہر کرتا ہے: اس لیے اس کے ہونٹوں سے چاپلوسی کرنے والے کے ساتھ مداخلت نہ کرو۔ {چاپلوسی: یا، لالچ}\n20۔ جو اپنے باپ یا ماں کو لعنت دے، اس کا چراغ دھندلے اندھیرے میں بجھا دیا جائے گا۔ {لیمپ: یا، موم بتی}\n21۔ ایک وراثت {ہو سکتی ہے} جو ابتدا میں جلدی حاصل کی گئی ہو؛ لیکن اس کا انجام بابرکت نہیں ہوگا۔\n22۔ یہ نہ کہو، میں برائی کا بدلہ دوں گا؛ {لیکن} خداوند کا انتظار کرو، اور وہ تمہیں بچا لے گا۔\n23. مختلف وزن خداوند کے لیے ایک مکروہ ہیں؛ اور غلط توازن اچھا نہیں ہے۔ {ایک جعلی...: عبرانی دھوکہ دہی کا توازن}\n24۔ انسان کے اعمال {ہیں} خداوند کے؛ تو پھر ایک آدمی اپنے طریقے کو کیسے سمجھ سکتا ہے؟\n25. {یہ اس شخص کے لیے جال ہے جو {جو ہے} مقدس چیز کو نگلتا ہے، اور بعد میں پوچھ گچھ کرنے کا عہد کرتا ہے۔\n26۔ ایک دانا بادشاہ بدکاروں کو منتشر کرتا ہے اور ان پر پہیہ لے آتا ہے۔\n27. انسان کی روح {ہے} خداوند کی موم بتی، جو پیٹ کے تمام اندرونی حصوں کو تلاش کرتی ہے۔ {موم بتی: یا، چراغ}\n28۔ رحم اور سچائی بادشاہ کو محفوظ رکھتی ہے: اور اس کا تخت رحم سے سہارا پاتا ہے۔\n29۔ نوجوانوں کی شان ان کی طاقت ہے: اور بوڑھوں کی خوبصورتی سرمئی سر ہے۔\n30۔ زخم کی نیلی پن برائی کو دور کر دیتی ہے: اسی طرح {do} پیٹ کے اندرونی حصوں پر دھاری دار ہو جاتا ہے۔ {پاکیزہ...: عبرانی۔ یہ صفائی کی دوا ہے}","1۔ بادشاہ کا دل خداوند کے ہاتھ میں ہے، جیسے پانی کی ندیاں: وہ اسے جہاں چاہے گھماتا ہے۔\n2۔ انسان کی ہر راہ اس کی اپنی نظر میں درست ہے: لیکن خداوند دلوں پر غور کرتا ہے۔\n3۔ انصاف اور فیصلہ کرنا خداوند کے لیے قربانی سے زیادہ قابل قبول ہے۔\n4۔ ایک بلند نظر، اور مغرور دل، {اور} بدکاروں کی ہل چلانا، {یہ} گناہ ہے۔ {این...: عبرانی۔ آنکھوں کی تکبر} {ہل چلانا: یا، روشنی}\n5۔ محنتی لوگوں کے خیالات صرف فراوانی کی طرف مائل ہوتے ہیں؛ لیکن ہر ایک {یعنی} صرف جلد بازی میں صرف چاہنے کے لیے۔\n6۔ خزانے کو جھوٹی زبان سے حاصل کرنا {ایک غرور ہے} جو موت کے خواہشمندوں کے درمیان پھینکا جاتا ہے۔\n7۔ بدکاروں کی لوٹ مار انہیں تباہ کر دے گی؛ کیونکہ وہ فیصلہ کرنے سے انکار کرتے ہیں۔ {تباہ کریں...: عببرانی۔ انہیں دیکھا، یا ان کے ساتھ رہا}\n8۔ انسان کا راستہ {ہے} بغاوت اور عجیب ہے: لیکن {پاکیزہ} کے لیے، اس کا کام {راست} ہے۔\n9. {گھر کی چھت کے کونے میں رہنا بہتر ہے، بجائے اس کے کہ ایک لڑائی کرنے والی عورت کے ساتھ وسیع گھر میں رہے۔ {ایک لڑائی...: عبوری۔ ایک تنازعہ کی عورت} {ایک وسیع...: عبرانی۔ ایک معاشرتی گھر}\n10۔ بدکار کی روح برائی کی خواہش رکھتی ہے: اس کا پڑوسی اس کی نظر میں کوئی پسندیدگی نہیں پاتا۔ {findeth...: عبوری۔ پسندیدہ نہیں ہے}\n11۔ جب مذاق کرنے والے کو سزا دی جاتی ہے، تو سادہ کو دانا بنایا جاتا ہے: اور جب دانا کو ہدایت دی جاتی ہے تو وہ علم حاصل کرتا ہے۔\n12. نیک {انسان} بدکاروں کے گھر کو دانشمندی سے دیکھتا ہے: {لیکن خدا} بدکاروں کو ان کی برائی کی وجہ سے گرا دیتا ہے۔\n13۔ جو بھی غریبوں کی پکار پر کان بند کرے گا، وہ خود بھی روئے، لیکن سنا نہیں جائے گا۔\n14. ایک تحفہ جو خفیہ طور پر غصے کو سکون دیتا ہے: اور سینے میں انعام شدید غصہ۔\n15۔ انصاف کرنے والوں کے لیے فیصلہ کرنا خوشی ہے: لیکن ظلم کرنے والوں کے لیے تباہی ہو گی۔\n16. جو شخص سمجھ بوجھ کے راستے سے بھٹک جائے گا وہ مردوں کی جماعت میں ہی رہے گا۔\n17. جو خوشی سے محبت کرتا ہے وہ غریب ہوگا: جو شراب اور تیل سے محبت کرتا ہے وہ امیر نہیں ہوگا۔ {خوشی: یا، کھیل}\n18۔ بدکار نیک لوگوں کے لیے فدیہ اور راستبازوں کے لیے بدکار ہوں گے۔\n19۔ {جنگل میں رہنا بہتر ہے} بجائے اس کے کہ ایک جھگڑالو اور غصے والی عورت کے ساتھ رہیں۔ {میں...: عبرانی صحرا کی سرزمین میں}\n20۔ عقلمندوں کے گھر میں خزانہ اور تیل ہے؛ لیکن ایک بے وقوف آدمی اسے خرچ کر دیتا ہے۔\n21۔ جو راستبازی اور رحمت کے بعد پیروی کرتا ہے وہ زندگی، راستبازی اور عزت پاتا ہے۔\n22۔ ایک دانا {انسان} طاقتوروں کے شہر پر چڑھتا ہے، اور اس کے اعتماد کی طاقت کو گرا دیتا ہے۔\n23۔ جو اپنی زبان اور زبان کو بچاتا ہے، وہ اپنی روح کو مصیبتوں سے بچاتا ہے۔\n24۔ مغرور {اور} مغرور شوخ {اس کا نام} ہے، جو فخر کے غصے کا شکار ہے۔ {فخر میں...: عبرانی میں۔ غرور کے غصے میں}\n25۔ سست لوگوں کی خواہش اسے مار دیتی ہے؛ کیونکہ اس کے ہاتھ محنت کرنے سے انکار کرتے ہیں۔\n26۔ وہ سارا دن لالچ میں لالچ کرتا ہے: لیکن نیک دینے والے دیتے ہیں اور کچھ نہیں چھوڑتے۔\n27۔ بدکار کی قربانی {ہے} مکروہ ہے: اور کتنی زیادہ، {جب} وہ اسے برے ذہن کے ساتھ لاتا ہے؟ {ساتھ...: عبوری۔ برائی میں؟}\n28۔ جھوٹا گواہ فنا ہو جائے گا: لیکن جو سنتا ہے وہ مسلسل بولتا ہے۔ {A...: عبرانی۔ جھوٹ کا گواہ}\n29۔ بدکار آدمی اپنا چہرہ سخت کر لیتا ہے: لیکن {جہاں تک} راست باز ہے، وہ اپنا راستہ دکھاتا ہے۔ {directeth: or, considereth}\n30۔ خداوند کے خلاف نہ حکمت، نہ سمجھ اور نہ نصیحت ہے۔\n31۔ گھوڑا جنگ کے دن کے لیے تیار کیا گیا ہے: لیکن حفاظت خداوند کی حفاظت ہے۔ {حفاظت: یا، فتح}","1. ایک {اچھا} نام {ہے} کو بڑی دولت سے بہتر منتخب کیا جانا چاہیے، {اور} محبت بھری عنایت کی بجائے چاندی اور سونے کے۔ {محبت...: یا، احسان بہتر ہے، وغیرہ}\n2۔ امیر اور غریب ایک ساتھ ملتے ہیں: خداوند سب کا خالق ہے۔\n3۔ ایک محتاط انسان برائی کی پیش گوئی کرتا ہے اور خود کو چھپاتا ہے: لیکن سادہ لوگ گزر جاتے ہیں اور سزا پاتے ہیں۔\n4۔ عاجزی اور خداوند کے خوف سے دولت، عزت اور زندگی ہے۔ {بذریعہ...: یا، عاجزی کا انعام، وغیرہ}\n5۔ کانٹے {اور} جال {ہیں} جو بغاوت کرنے والے کے راستے میں ہیں: جو اپنی روح کو سنبھالے گا وہ ان سے دور ہوگا۔\n6۔ بچے کو اس راستے پر تربیت دیں جس پر اسے جانا چاہیے: اور جب وہ بوڑھا ہو جائے تو وہ اس سے نہ ہٹے۔ {ٹرین...: یا، کیٹیکیز} {میں...: عبرانی اپنے انداز میں}\n7۔ امیر غریبوں پر حکمرانی کرتا ہے، اور قرض لینے والا قرض دینے والے کا خادم ہے۔ {قرض دہندہ: عبرانی۔ وہ آدمی جو قرض دیتا ہے}\n8۔ جو بدکاری کرے گا، وہ باطل کاٹے گا: اور اس کے غصے کی چھڑی ناکام ہو جائے گی۔ {چھڑی...: یا، اس کے غصے کی چھڑی سے اسے نگل لیا جائے گا}\n9۔ جس کی نظر خوبصورت ہو اسے برکت ملے گی؛ کیونکہ وہ اپنی روٹی غریبوں کو دیتا ہے۔ {وہ جو...: عبرانی آنکھ اچھی ہے\n10۔ جھنڈے کو نکال دو، اور تنازعہ ختم ہو جائے گا؛ ہاں، جھگڑا اور ملامت ختم ہو جائے گی۔\n11۔ جو دل کی پاکیزگی سے محبت کرتا ہے، {کیونکہ اس کے ہونٹوں کی رحمت سے بادشاہ اس کا دوست ہوگا}۔ {کیونکہ...: یا، اور اس کے ہونٹوں میں فضل ہے}\n12۔ خداوند کی آنکھیں علم کو محفوظ رکھتی ہیں، اور وہ مجرم کے الفاظ کو الٹ دیتا ہے۔ {الفاظ: یا، معاملات}\n13۔ سست آدمی کہتا ہے، {شیر کے باہر ہے}، میں سڑکوں پر مارا جاؤں گا۔\n14۔ اجنبی عورتوں کا منہ ایک گہرا گڑھا ہے: جو خداوند سے نفرت کرے گا وہ اس میں گر جائے گا۔\n15۔ حماقت بچے کے دل میں بندھی ہوئی ہے؛ {لیکن} اصلاح کی چھڑی اسے اس سے دور لے جائے گی۔\n16۔ جو غریبوں پر ظلم کرتا ہے تاکہ اس کی دولت بڑھے، اور جو امیروں کو دیتا ہے، وہ یقینا محتاج ہو جائے گا۔\n17۔ اپنا کان جھکاؤ، اور دانا کے الفاظ سنو، اور اپنے دل کو میرے علم پر لاگو کرو۔\n18۔ کیونکہ اگر تم انہیں اپنے اندر رکھو تو یہ ایک خوشگوار چیز ہے؛ وہ ہمیشہ تمہارے ہونٹوں میں فٹ ہوں گے۔ {اندر...: عبرانی تمہارے پیٹ میں}\n19۔ تاکہ تمہارا بھروسہ خداوند پر ہو، میں نے آج تمہیں اور تمہیں بھی بتا دیا ہے۔ {حتیٰ کہ...: یا، تم بھی بھروسہ کرو}\n20. کیا میں نے تمہیں نصیحت اور علم میں عمدہ باتیں نہیں لکھی ہیں،\n21۔ تاکہ میں تمہیں سچائی کے الفاظ کی یقین دہانی کراؤں؛ تاکہ تم ان لوگوں کو سچائی کے الفاظ کا جواب دے سکو جو تمہیں بھیجتے ہیں؟ {ان کے لیے...: یا، ان کے لیے جو تمہیں بھیجتے ہیں؟}\n22. غریبوں کو نہ لوٹنا، کیونکہ وہ {غریب} ہے: نہ ہی دروازے پر مصیبت زدہ کو ظلم کرتے:\n23. کیونکہ خداوند ان کے مقصد کی وکالت کرے گا، اور ان کی روح کو خراب کرے گا جنہوں نے انہیں بگاڑا۔\n24۔ غصے والے آدمی سے دوستی نہ کرو؛ اور ایک غصے والے آدمی کے ساتھ تم نہیں جاؤ گے:\n25. کہیں تم اس کے طریقے نہ سیکھو اور اپنی روح کو پھنساؤ۔\n26. ہاتھ مارنے والوں میں سے {ایک} نہ بنو، {یا} ان میں سے جو قرضوں کے ضامن ہوں۔\n27۔ اگر تمہارے پاس کچھ ادا کرنے کو نہیں، تو وہ تمہارا بستر تمہارے نیچے سے کیوں چھینے؟\n28۔ وہ قدیم نشان نہ ہٹاؤ جو تمہارے آباؤ اجداد نے قائم کی ہے۔ {لینڈ مارک: اور، باؤنڈ}\n29۔ کیا تم نے دیکھا ہے کہ کوئی آدمی اپنے کام میں محنتی ہے؟ وہ بادشاہوں کے سامنے کھڑا ہوگا؛ وہ ظالم لوگوں کے سامنے نہیں کھڑا ہوگا۔ {مطلب...: عبرانی۔ مبہم مرد}","1۔ جب آپ حکمران کے ساتھ کھانے کے لیے بیٹھیں، تو غور سے دیکھیں کہ آپ کے سامنے کیا ہے:\n2۔ اور اگر تم بھوک میں مبتلا ہو تو اپنے گلے پر چھری رکھو۔\n3۔ اس کی لذیذ چیزوں کی خواہش نہ کرو: کیونکہ وہ دھوکہ باز گوشت ہیں۔\n4۔ امیر نہ ہونے کے لیے محنت کرو: اپنی حکمت سے رک جاؤ۔\n5. کیا تم اپنی نظر اس چیز پر ڈالو گے جو نہیں ہے؟ کیونکہ {دولت} یقینی طور پر اپنے آپ کو پر بناتی ہیں؛ وہ عقاب کی طرح آسمان کی طرف اڑتے ہیں۔ {سیٹ...: عبوری۔ اپنی آنکھیں اوپر اٹھا دو}\n6۔ جس کی نظر بری ہے اس کی روٹی نہ کھاؤ، نہ اس کے نازک گوشت کی خواہش کرو:\n7۔ جیسا وہ اپنے دل میں سوچتا ہے، ویسے ہی وہ: کھاؤ اور پیو، وہ تم سے کہتا ہے؛ لیکن اس کا دل تمہارے ساتھ نہیں ہے۔\n8۔ وہ ٹکڑا جو تم نے کھایا ہے، وہ تم الٹی کرو گے، اور اپنی میٹھی باتیں کھو دو گے۔\n9۔ کسی بے وقوف کے کانوں میں بات نہ کرو، کیونکہ وہ تمہاری باتوں کی حکمت کو حقیر سمجھے گا۔\n10. پرانا نشان نہ ہٹایا جائے؛ اور یتیم کے کھیتوں میں نہ جاؤ: {نشان: یا، بند}\n11۔ کیونکہ ان کا نجات دہندہ {ہے} طاقتور ہے؛ وہ تمہارے سامنے ان کا مقدمہ اٹھائے گا۔\n12. اپنے دل کو تعلیم کے لیے وقف کرو، اور اپنے کان علم کے الفاظ پر۔\n13۔ بچے سے اصلاح نہ روکو: کیونکہ اگر تم اسے چھڑی سے مارو گے تو وہ نہیں مرے گا۔\n14۔ تو اسے چھڑی سے مارو گے، اور اس کی روح کو جہنم سے آزاد کرو گے۔\n15۔ میرے بیٹے، اگر تمہارا دل دانا ہے تو میرا دل بھی خوش ہوگا، میرا بھی۔ {حتیٰ کہ...: یا، میں بھی خوش رہوں گا}\n16۔ ہاں، میری لگام خوش ہوں گی، جب تمہارے ہونٹ صحیح باتیں کریں گے۔\n17۔ اپنا دل گناہ گاروں سے حسد نہ کرے، بلکہ {تو سارا دن خداوند کے خوف میں رہو}۔\n18. کیونکہ یقینا ایک اختتام ہے؛ اور تمہاری امید کبھی ختم نہیں ہوگی۔ {اختتام: یا، انعام}\n19۔ سنو، میرے بیٹے، اور دانا بنو، اور اپنے دل کی رہنمائی کرو۔\n20. شراب پینے والوں میں شامل نہ ہوں؛ گوشت کھانے والوں میں: {گوشت کا: عبرانی۔ ان کے جسم کی}\n21۔ کیونکہ شرابی اور لالچی غربت میں آ جائیں گے: اور نیند انسان کو کپڑے پہنائے گی۔\n22۔ اپنے والد کی سنو جس نے تمہیں جنم دیا، اور اپنی ماں کو بوڑھی ہونے پر حقیر نہ سمجھو۔\n23۔ سچائی خریدو، اور اسے نہ بیچو؛ {نیز}حکمت، ہدایت، اور سمجھ بوجھ بھی۔\n24۔ راستبازوں کا باپ بہت خوش ہوگا: اور جو دانا بچے کو پیدا کرے گا وہ اس سے خوش ہوگا۔\n25۔ تمہارا باپ اور تمہاری ماں خوش ہوں گے، اور جو تمہیں جنم دے گی وہ خوش ہوگی۔\n26۔ میرے بیٹے، اپنا دل مجھے دو، اور اپنی آنکھیں میرے راستوں پر نظر رکھو۔\n27. ایک طوائف کے لیے {ہے} ایک گہرا کھائی ہے؛ اور ایک اجنبی عورت ایک تنگ گڑھا ہے۔\n28۔ وہ بھی شکار کے طور پر انتظار میں رہتی ہے، اور انسانوں میں نافرمان افراد کو بڑھاتی ہے۔ {جہاں تک کہ...: یا، ڈاکو کے طور پر}\n29۔ کس کو افسوس ہے؟ کس کے پاس غم ہے؟ کس کے پاس اختلافات ہیں؟ کون بکواس کر رہا ہے؟ کون بغیر وجہ کے زخم دیتا ہے؟ کس کی آنکھیں لال ہیں؟\n30۔ جو لوگ شراب میں دیر تک ٹھہرتے ہیں؛ وہ جو مکسڈ وائن کی تلاش میں جاتے ہیں۔\n31۔ شراب کو مت دیکھو جب وہ سرخ ہو، جب وہ پیالے میں اپنا رنگ دے، {جب} وہ خود کو سیدھا حرکت کرے۔\n32۔ آخر میں یہ سانپ کی طرح کاٹتا ہے، اور چب کی طرح ڈنک مارتا ہے۔ {ایک...: یا، ایک کاکاٹریس}\n33۔ تمہاری آنکھیں اجنبی عورتوں کو دیکھیں گی، اور تمہارا دل عجیب باتیں کرے گا۔\n34۔ ہاں، تم ویسے ہی بنو گے جیسے وہ سمندر کے بیچ لیٹا ہے، یا جو کسی مستول کی چوٹی پر لیٹا ہو۔ {درمیان...: عبرانی سمندر کا دل}\n35۔ انہوں نے مجھے متاثر کیا ہے، {تم کہو گے، اور} میں بیمار نہیں تھا؛ انہوں نے مجھے مارا ہے، {اور} میں نے محسوس نہیں کیا: میں کب جاگوں گا؟ میں اسے دوبارہ تلاش کروں گا۔ {میں نے محسوس کیا...: عبرانی۔ مجھے معلوم نہیں تھا}","1۔ برے لوگوں سے حسد نہ کرو، نہ ہی ان کے ساتھ رہنے کی خواہش کرو۔\n2۔ کیونکہ ان کا دل تباہی کو پڑھتا ہے، اور ان کے ہونٹ شرارت کی باتیں کرتے ہیں۔\n3۔ حکمت سے ایک گھر تعمیر ہوتا ہے؛ اور سمجھ بوجھ سے یہ ثابت ہوتا ہے:\n4۔ اور علم سے کمرے قیمتی اور خوشگوار خزانے سے بھر جائیں گے۔\n5۔ ایک دانا آدمی {ہے} مضبوط ہے؛ ہاں، علم رکھنے والا انسان طاقت بڑھاتا ہے۔ {مضبوط ہے: عبرانی۔ طاقت میں ہے} {بڑھاؤ...: عبرانی۔ طاقت کو مضبوط کرنا}\n6۔ کیونکہ دانشمندانہ مشورے سے تم اپنی جنگ لڑو گے: اور مشیروں کی کثرت میں حفاظت ہوگی۔\n7۔ حکمت ایک بے وقوف کے لیے بہت بلند ہے: وہ دروازے میں اپنا منہ نہیں کھولتا۔\n8۔ جو برائی کرنے کی سازش کرے گا اسے شرارتی کہا جائے گا۔\n9۔ حماقت کا خیال {ہے} گناہ ہے: اور مذاق اڑانا {ہے} انسانوں کے لیے مکروہ ہے۔\n10. {اگر} تم مشکل کے دن بے ہوش ہو جاؤ، تو تمہاری طاقت {کمزور} ہے۔ {چھوٹا: عبرانی۔ تنگ}\n11۔ اگر تم ان لوگوں کو بچانے سے باز رہو جو موت کی طرف کھینچے جا رہے ہیں، اور جو مارے جانے کے لیے تیار ہیں؛\n12۔ اگر تم کہتے ہو، دیکھو، ہم اسے نہیں جانتے تھے؛ کیا جو دل پر غور کرتا ہے وہ اس پر غور نہیں کرتا؟ اور جو تمہاری روح کو سنبھالتا ہے، کیا وہ اسے نہیں جانتا؟ اور کیا وہ {نہیں} ہر انسان کو اس کے اعمال کے مطابق پیش کرے گا؟\n13۔ میرے بیٹے، شہد کھاؤ، کیونکہ یہ اچھا ہے؛ اور شہد کا چھتا، {جو} تمہارے ذائقے کے مطابق میٹھا ہے: {تو...: عبرانی تمہارے ذائقے پر}\n14۔ اسی طرح حکمت کا علم تمہاری روح تک پہنچے گا: جب تم اسے پا لو گے، تب انعام ملے گا، اور تمہاری امید ختم نہیں ہوگی۔\n15. اے بدکار {انسان}، راستبازوں کے گھر کے خلاف انتظار نہ کرو؛ اس کی آرام گاہ کو خراب نہ کرو:\n16۔ کیونکہ ایک عادل {انسان} سات بار گرتا ہے اور دوبارہ اٹھتا ہے: لیکن بدکار شرارت میں گر جاتا ہے۔\n17۔ اپنے دشمن کے گرنے پر خوش نہ ہو، اور جب وہ لڑکھڑاتا ہے تو تمہارا دل خوش نہ ہو:\n18. خدا اسے دیکھ کر ناراض نہ ہو اور وہ اپنا غضب اس سے موڑ لے۔ {یہ ناپسندیدہ ہے...: عبرانی۔ یہ اس کی نظر میں برائی ہے}\n19۔ برائی کی وجہ سے خود کو فکر نہ کرو، نہ ہی بدکاروں سے حسد کرو؛ {پریشان...: یا، بدکاروں کے ساتھ صحبت نہ کرو}\n20. کیونکہ برے انسان کو کوئی انعام نہیں ملے گا؛ بدکاروں کی شمع بجھائی جائے گی۔ {موم بتی: یا، چراغ}\n21. میرے بیٹے، خداوند اور بادشاہ سے ڈرو: {اور} ان لوگوں میں مداخلت نہ کرو جو بدلنے کے لیے دیے گئے ہیں: {وہ...: عبرانی۔ چینجرز}\n22۔ کیونکہ ان کی آفت اچانک اٹھے گی؛ اور کون جانتا ہے کہ ان دونوں کی بربادی کیا ہے؟\n23. یہ {چیزیں} بھی *عقلمندوں کی ملکیت ہیں}۔ {فیصلہ کرنے والوں کی عزت کرنا اچھا نہیں ہے۔\n24۔ جو بدکاروں سے کہتا ہے، تو {راستباز} ہو؛ لوگ اسے لعنت دیں گے، قومیں اس سے نفرت کریں گی:\n25۔ لیکن جو لوگ اسے ملامت کریں گے، ان کے لیے خوشی ہوگی، اور ان پر نیک برکت آئے گی۔ {ایک اچھا...: عببرانی۔ ایک نیکی کی برکت}\n26۔ {ہر آدمی} ان {اپنی} ہونٹوں کو چومے گا جو صحیح جواب دیتے ہیں۔ {وہ...: عببرانی۔ جو صحیح الفاظ کا جواب دیتا ہے}\n27۔ اپنے کام کو باہر تیار کرو، اور اسے میدان میں اپنے لیے موزوں بنا؛ اور بعد میں اپنا گھر تعمیر کرو۔\n28۔ بغیر وجہ کے اپنے پڑوسی کے خلاف گواہ نہ بنو؛ اور اپنے ہونٹوں سے دھوکہ نہیں دینا۔\n29۔ یہ نہ کہو، میں اس کے ساتھ ویسا ہی کروں گا جیسا اس نے میرے ساتھ کیا: میں اس آدمی کو اس کے کام کے مطابق دوں گا۔\n30۔ میں سست لوگوں کے کھیت اور اس آدمی کے انگور کے باغ سے گزرا جو سمجھ سے خالی تھا؛\n31۔ اور، دیکھو، یہ سب کانٹوں سے ڈھکا ہوا تھا، {اور} اس کے چہرے پر بچھو کے پھول تھے، اور اس کی پتھر کی دیوار ٹوٹ چکی تھی۔\n32. پھر میں نے دیکھا، {اور} نے {اسے} کو اچھی طرح دیکھا: میں نے {اسے} کو دیکھا، اور} کو ہدایت ملی۔ {غور کیا...: عبرانی۔ میرا دل سیٹ کرو}\n33۔ {ابھی} تھوڑی نیند، تھوڑی نیند، ہاتھ جوڑ کر سونے کے لیے:\n34. اسی طرح تمہاری غربت آئے گی {ویسے} جیسے وہ سفر کرتا ہے؛ اور تمہاری خواہش ایک مسلح آدمی کے طور پر۔ {an...: عبرانی۔ ڈھال کا آدمی}","1۔ یہ بھی سلیمان کے امثال ہیں، جنہیں یہوداہ کے بادشاہ حزقیاہ کے لوگوں نے نقل کیا۔\n2. {یہ خدا کی شان ہے} کہ وہ کسی چیز کو چھپائے: لیکن بادشاہوں کی عزت {ہے} کہ وہ کسی معاملے کو تلاش کریں۔\n3۔ آسمان بلندی کے لیے، زمین گہرائی کے لیے، اور بادشاہوں کا دل ناقابل تلاش ہے۔ {ہے...: عبرانی۔ کوئی تلاش نہیں ہے}\n4۔ چاندی سے فضلہ نکالو، تو نفیس کے لیے ایک برتن نکلے گا۔\n5۔ بادشاہ کے سامنے بدکاروں کو ہٹا دو، اور اس کا تخت راستبازی میں قائم ہو جائے گا۔\n6۔ بادشاہ کے سامنے خود کو پیش نہ کرو، اور عظیم لوگوں کی جگہ نہ کھڑا ہو: {رکھو...: عبرانی۔ اپنی شان و شوکت کو باہر نہ رکھو}\n7. بہتر ہے کہ تم سے کہا جائے، یہاں آؤ؛ اس سے کہ تمہیں اس شہزادے کے سامنے نیچے رکھا جائے جسے تمہاری آنکھوں نے دیکھا ہے۔\n8۔ جلدی میں کوشش نہ کرو، ورنہ {تمہیں} معلوم نہیں کہ آخر میں کیا کرنا ہے، جب تمہارا پڑوسی تمہیں شرمندہ کر دے۔\n9۔ اپنے معاملے پر اپنے پڑوسی سے بحث کرو؛ اور کسی اور سے کوئی راز نہ دریافت کرو: {ایک راز...: یا، راز کا}\n10۔ تاکہ جو سنتا ہے وہ تمہیں شرمندہ نہ کرے، اور تمہاری بدنامی منہ نہ موڑے۔\n11۔ ایک لفظ جو مناسب انداز میں بولا جائے {وہ چاندی کی تصویروں میں سونے کے سیبوں کی طرح ہے۔ {فٹلی...: عبرانی۔ اس کے پہیوں پر بولی}\n12۔ {سونے کی بالی} اور عمدہ سونے کا زیور، {اسی طرح} فرمانبردار کان پر عقلمند ریکارر ہے۔\n13۔ جیسے فصل کے وقت برف کی سردی ہوتی ہے، {ویسے} ایک وفادار پیغام رساں بھی ہے جو اسے بھیجتا ہے: کیونکہ وہ اپنے آقا کی روح کو تازہ کرتا ہے۔\n14. جو خود کو جھوٹے تحفے پر فخر کرتا ہے {وہ بادلوں اور ہوا کی طرح ہے بغیر بارش کے۔ {ایک...: عبرانی جھوٹ کے تحفے میں}\n15. طویل صبر سے شہزادہ قائل ہو جاتا ہے، اور نرم زبان ہڈی توڑ دیتی ہے۔\n16۔ کیا تم نے شہد ڈھونڈ لیا؟ جتنا تمہارے لیے کافی ہو کھاؤ، ورنہ تم اس سے بھر جاؤ گے اور قے کر دو گے۔\n17۔ اپنے پڑوسی کے گھر سے پاؤں ہٹا لو؛ تاکہ وہ تم سے تنگ نہ آئے، اور تم سے نفرت نہ کرے۔ {پیچھے ہٹو...: یا، تمہارا قدم شاذ و نادر ہی اندر آئے} {تھکا ہوا...: عبرانی۔ تم سے بھرا ہوا}\n18۔ جو آدمی اپنے پڑوسی کے خلاف جھوٹی گواہی دیتا ہے وہ ایک تلوار، تلوار اور تیز تیر ہے۔\n19۔ مشکل وقت میں بے وفا آدمی پر اعتماد ایسا ہے جیسے ٹوٹا ہوا دانت اور جوڑ سے باہر ہو جائے۔\n20۔ {ویسے} جو سرد موسم میں لباس اتارتا ہے، {اور جیسے سرکہ نائٹر پر سرکہ}، ویسے ہی وہی ہے جو بھاری دل کے لیے گانا گاتا ہے۔\n21۔ اگر تمہارا دشمن بھوکا ہے تو اسے کھانے کے لیے روٹی دو؛ اور اگر اسے پیاس لگے تو اسے پینے کے لیے پانی دو:\n22۔ کیونکہ تم اس کے سر پر آگ کے کوئلے ڈالو گے، اور خداوند تمہیں اجر دے گا۔\n23. شمالی ہوا بارش کو بھگا دیتی ہے: اسی طرح غصے والا چہرہ ایک غیبت کرنے والی زبان ہے۔ {چلتا ہے...: یا، بارش لاتا ہے: اسی طرح غیبت کرنے والی زبان غصے میں مبتلا چہرہ بھی کرتی ہے}\n24۔ {گھر کی چھت کے کونے میں رہنا بہتر ہے، بجائے اس کے کہ لڑائی کرنے والی عورت کے ساتھ اور ایک وسیع گھر میں رہو۔\n25۔ {جیسا کہ} پیاسی روح کے لیے ٹھنڈا پانی، اسی طرح {ہے} ایک دور دراز ملک سے خوشخبری۔\n26۔ ایک نیک آدمی جو بدکاروں کے سامنے گرتا ہے {یہ ایک پریشان چشمہ اور ایک خراب چشمہ کی طرح ہے}۔\n27. {زیادہ شہد کھانا اچھا نہیں}: اسی طرح {انسانوں کے لیے} اپنی شان تلاش کرنا {جلال نہیں} ہے۔\n28۔ جو اپنی روح پر {حکمرانی} نہیں رکھتا، وہ ایک ایسے شہر کی مانند ہے {جو ٹوٹ پھوٹ کا شکار ہو}، {اور} بغیر دیواروں کے۔","1۔ جیسے گرمیوں میں برف، اور فصل کی بارش کی طرح، عزت بھی احمق کے لیے مناسب نہیں۔\n2۔ جیسے پرندہ بھٹکتا ہے، جیسے ابال اڑتا ہے، ویسے ہی بے وجہ لعنت نہیں آئے گی۔\n3۔ گھوڑے کے لیے کوڑا، گدھے کے لیے لگام، اور بیوقوف کی پیٹھ کے لیے چھڑی۔\n4۔ کسی بے وقوف کو اس کی حماقت کے مطابق جواب نہ دو، ورنہ تم بھی اس جیسے ہو جاؤ گے۔\n5۔ کسی بے وقوف کو اس کی حماقت کے مطابق جواب دو، ورنہ وہ اپنی خود پسندی میں دانا ہو جائے گا۔ {مفروضہ: عبرانی۔ آنکھیں}\n6۔ جو احمق کے ہاتھ سے پیغام بھیجتا ہے، وہ اپنے پاؤں کاٹ دیتا ہے، {اور} نقصان پیتا ہے۔ {نقصان: یا، تشدد}\n7. لنگڑے کی ٹانگیں برابر نہیں: یوں {ہے} بیوقوفوں کے منہ میں ایک تمثیل ہے۔ {آر...: عبرانی اٹھا دیے گئے ہیں}\n8. جیسے جو پتھر کو سلنگ میں باندھتا ہے، ویسے ہی وہ احمق کو عزت دیتا ہے۔ {باندھ...: یا، قیمتی پتھر کو پتھروں کے ڈھیر میں رکھ دو}\n9. {جیسے کانٹا} نشے میں دھت کے ہاتھ میں چڑھ جاتا ہے، ویسے ہی {ہے} بیوقوفوں کے منہ میں ایک تمثیل ہے۔\n10۔ عظیم خدا جس نے تمام چیزیں بنائی ہیں، وہ بیوقوف کو اجر دیتا ہے اور نافرمان کو بھی اجر دیتا ہے۔ {عظیم...: یا، ایک عظیم آدمی سب کو غمگین کرتا ہے، اور وہ بیوقوف کو ملازمت دیتا ہے، وہ نافرمان بھی رکھتا ہے}\n11۔ جیسے کتا اپنی قے کی طرف لوٹتا ہے، ویسے ہی بے وقوف اپنی حماقت کی طرف لوٹتا ہے۔ {اپنی حماقت کی طرف لوٹتا ہے: عبرانی۔ اپنی حماقت کو دہراتا ہے}\n12. کیا تم دیکھتے ہو کہ ایک دانا آدمی اپنے غرور میں ہے؟ ایک بے وقوف کی امید اس سے زیادہ ہے۔\n13۔ سست {انسان} کہتا ہے، {راستے میں شیر ہے}؛ ایک شیر سڑکوں پر ہے۔\n14۔ جیسے ہی دروازہ اس کے قبضوں پر گھومتا ہے، ویسے ہی سست اپنے بستر پر گھومتا ہے۔\n15۔ سست شخص اپنا ہاتھ {اپنی} کے سینے میں چھپا لیتا ہے؛ اسے دوبارہ منہ تک لانا اسے دکھ دیتا ہے۔ {یہ غمگین ہے...: یا، وہ تھکا ہوا ہے}\n16. سست شخص اپنے غرور میں سات آدمیوں سے زیادہ عقلمند ہوتا ہے جو دلیل دے سکتے ہیں۔\n17. جو گزرتا ہے، {اور} اس لڑائی میں الجھتا ہے جو اس کا نہیں ہے، {ایسا ہے} جو کتے کو کان پکڑ لیتا ہے۔ {مڈلتھ: یا، غصے میں ہے}\n18. ایک پاگل {آدمی} کے طور پر جو آگ کے جھٹکے، تیر اور موت پھینکتا ہے، {آگ لگانے والے: عبرانی۔ شعلے یا، چنگاریاں}\n19۔ تو کیا وہ آدمی ہے جو اپنے پڑوسی کو دھوکہ دیتا ہے اور کہتا ہے، کیا میں مذاق میں نہیں ہوں؟\n20۔ جہاں لکڑی نہیں ہوتی، وہاں آگ بجھ جاتی ہے: اسی طرح جہاں کہانی سنانے والا نہیں ہوتا، لڑائی ختم ہو جاتی ہے۔ {جہاں نہیں...: عبوری۔ بغیر لکڑی کے} {قصہ بردار: یا، سرگوشی} {بس: عبرانی۔ خاموش ہے}\n21۔ {جیسا کہ کوئلہ} جلتے ہوئے کوئلے کے لیے ہیں، اور لکڑی آگ کے لیے؛ لہٰذا وہ ایک متنازعہ شخص ہے جو تنازعہ کو ہوا دیتا ہے۔\n22۔ کہانی سنانے والے کے الفاظ زخموں کی طرح ہوتے ہیں، اور وہ پیٹ کے سب سے اندرونی حصوں تک پہنچتے ہیں۔ {سب سے اندر...: عببرانی۔ چیمبرز}\n23۔ جلتے ہوئے ہونٹ اور بد دل {جیسے چاندی کے ٹکڑے سے ڈھکا ہوا مٹی کا ٹکڑا ہو۔\n24۔ جو نفرت کرتا ہے وہ اپنے ہونٹوں سے دھوکہ دکھاتا ہے اور اپنے اندر دھوکہ دکھاتا ہے؛ {dissembleth: or, is known}\n25۔ جب وہ صاف بولے تو اس پر یقین نہ کرو: کیونکہ اس کے دل میں سات گناہ ہیں۔ {بولتا ہے...: عبرانی۔ اس کی آواز کو مہربان بناتی ہے}\n26۔ {جس کی} نفرت دھوکہ دہی سے چھپی ہو، اس کی بدکاری پوری جماعت کے سامنے ظاہر ہوگی۔ {بائی...: یا، خفیہ طور پر}\n27۔ جو کوئی گڑھا کھودے گا وہ اس میں گر جائے گا: اور جو پتھر لڑھائے گا، وہ اس پر واپس آئے گا۔\n28۔ جھوٹی زبان ان لوگوں سے نفرت کرتی ہے جو اس سے متاثر ہوتے ہیں؛ اور ایک خوشامد کرنے والا منہ تباہی کا باعث بنتا ہے۔","1۔ کل کے لیے فخر نہ کرو؛ کیونکہ تم نہیں جانتے کہ ایک دن کیا لے کر آ سکتا ہے۔ {تو...: عبرانی ٹو مورو ڈے}\n2۔ کوئی اور تمہاری تعریف کرے، نہ کہ تمہارے اپنے منہ کو؛ ایک اجنبی، اور تمہارے اپنے ہونٹ نہیں۔\n3۔ پتھر بھاری ہے، اور ریت بھاری ہے؛ لیکن ایک بے وقوف کا غصہ دونوں سے زیادہ بھاری ہوتا ہے۔ {ہیوی: ہیب۔ بھاری پن}\n4. غصہ {ہے} ظالم، اور غصہ {ہے} حد سے زیادہ؛ لیکن حسد کے سامنے کون کھڑا ہو سکتا ہے؟ {غصہ...: عبرانی۔ غصہ ظلم ہے، اور غصہ ایک سیلاب ہے} {حسد: یا، حسد؟}\n5. کھلا سرزنش خفیہ محبت سے بہتر ہے۔\n6۔ وفادار دوست کے زخم ہیں؛ لیکن دشمن کے بوسے دھوکہ دہی والے ہوتے ہیں۔ {دھوکہ دہی: یا، سنجیدہ، یا، اکثر}\n7۔ مکمل روح شہد کے چھتے سے نفرت کرتی ہے؛ لیکن بھوکی روح کے لیے ہر کڑوا چیز میٹھی ہے۔ {ناپسندیدہ: عبرانی۔ ٹریڈتھ انڈر پاؤڈ}\n8. جیسے پرندہ اپنے گھونسلے سے بھٹکتا ہے، ویسے ہی انسان اپنی جگہ سے بھٹکتا ہے۔\n9۔ مرہم اور خوشبو دل کو خوش کرتی ہے: اسی طرح انسان کے دوست کی مٹھاس دل سے نصیحت سے ہوتی ہے۔ {بذریعہ...: عبرانی۔ روح کے مشورے سے}\n10۔ اپنے دوست، اور اپنے والد کے دوست، نہ چھوڑو؛ نہ اپنے بھائی کے گھر میں اپنے مصیبت کے دن جانا: {کیونکہ} قریبی پڑوسی {یعنی} دور بھائی سے بہتر ہے۔\n11۔ میرے بیٹے، دانا بنو اور میرا دل خوش کر دو، تاکہ میں اس کا جواب دے سکوں جو مجھے ملامت کرتا ہے۔\n12۔ ایک محتاط {انسان} برائی کی پیش گوئی کرتا ہے، {اور} خود کو چھپاتا ہے؛ {لیکن} سادہ طور پر آگے بڑھنے پر، {اور} کو سزا ملتی ہے۔\n13۔ اس کا وہ لباس لے لو جو کسی اجنبی کے لیے ضمانت ہے، اور اسے اجنبی عورت کے طور پر گروی رکھو۔\n14۔ جو اپنے دوست کو بلند آواز میں برکت دیتا ہے، صبح سویرے اٹھتا ہے، اسے لعنت سمجھا جائے گا۔\n15۔ بارش والے دن میں مسلسل گرنا اور جھگڑالو عورت ایک جیسے ہیں۔\n16۔ جو اسے چھپاتا ہے وہ ہوا اور اپنے دائیں ہاتھ کی مرہم کو چھپاتا ہے، {جو} خود کو چھپاتا ہے۔\n17۔ لوہا تیز لوہا؛ تو ایک آدمی اپنے دوست کے چہرے کو تیز کرتا ہے۔\n18۔ جو انجیر کا درخت رکھے گا وہ اس کا پھل کھائے گا: تاکہ جو اپنے مالک کا انتظار کرے گا وہ عزت کرے گا۔\n19۔ جیسے پانی کا چہرہ سامنے آتا ہے، ویسے ہی انسان کا دل انسان سے ملتا ہے۔\n20۔ جہنم اور تباہی کبھی مکمل نہیں ہوتیں؛ اس لیے انسان کی آنکھیں کبھی مطمئن نہیں ہوتیں۔ {کبھی نہیں: عبرانی۔ نہیں}\n21۔ چاندی کے لیے فائننگ برتن اور سونے کے لیے بھٹی؛ تو {ہے} اس کی تعریف کے قابل مرد۔\n22۔ اگرچہ تم گندم کے درمیان مونے میں ایک بے وقوف کو ہاتھ سے پکارو، {لیکن} اس کی حماقت اس سے دور نہیں ہوگی۔\n23۔ اپنے ریوڑ کی حالت جاننے کے لیے محنتی رہو، {اور} اپنے ریوڑ پر اچھی طرح نظر رکھو۔ {دیکھیں...: عبوری۔ اپنا دل سیٹ کرو}\n24۔ کیونکہ دولت ہمیشہ کے لیے نہیں: اور کیا تاج ہر نسل تک قائم رہتا ہے؟ {دولت: عبرانی۔ strength} {to...: عبرانی نسل اور نسل کے لیے؟}\n25۔ گھاس نمودار ہوتی ہے، اور نرم گھاس خود کو ظاہر کرتی ہے، اور پہاڑوں کی جڑی بوٹیاں جمع کی جاتی ہیں۔\n26. بکری تمہارے کپڑوں کے لیے ہیں، اور بکریاں کھیت کی قیمت ہیں۔\n27۔ اور {تمہیں} بکری کا دودھ ملے گا جو تمہارے کھانے، اپنے گھرانے کے کھانے کے لیے، اور تمہاری لڑکیوں کی کفالت کے لیے کافی ہو۔ {مینٹیننس: ہیب۔ زندگی}","1۔ بدکار بھاگ جاتے ہیں جب کوئی پیچھا نہ کرے: لیکن نیک شیر کی طرح بہادر ہوتے ہیں۔\n2۔ کسی زمین کی خلاف ورزی پر بہت سے اس کے بادشاہ ہیں: لیکن ایک سمجھدار اور علم رکھنے والے شخص کی وجہ سے اس کی حالت طویل ہو جائے گی۔ {بذریعہ ...: یا، سمجھدار اور دانا لوگوں کے ذریعے انہیں بھی طویل کیا جائے گا}\n3۔ ایک غریب آدمی جو غریبوں پر ظلم کرتا ہے {وہ ایک تیز بارش کی مانند ہے جو خوراک نہیں چھوڑتی۔ {جو کہ...: عبرانی بغیر کھانے کے}\n4۔ جو قانون کو ترک کرتے ہیں وہ بدکاروں کی تعریف کرتے ہیں: لیکن جو قانون کی پابندی کرتے ہیں وہ ان سے لڑتے ہیں۔\n5۔ برے لوگ فیصلے کو نہیں سمجھتے: لیکن جو خداوند کی تلاش کرتے ہیں وہ سب کچھ سمجھتے ہیں۔\n6. وہ غریب جو اپنی راستبازی میں چلتا ہے، بہتر ہے بجائے اس کے کہ وہ جو اپنے راستوں میں بگڑا ہوا ہو، چاہے وہ امیر کیوں نہ ہو۔\n7۔ جو قانون کی پابندی کرتا ہے وہ دانا بیٹا ہے: لیکن جو شرارتی لوگوں کا ساتھی ہے وہ اپنے باپ کو شرمندہ کرتا ہے۔ {ایک ساتھی ہے...: یا، لالچیوں کو کھلاتا ہے}\n8۔ جو جو سود اور ناجائز فائدے سے اپنی دولت بڑھاتا ہے، وہ اسے اس کے لیے جمع کرے گا جو غریبوں پر رحم کرے گا۔ {ناانصافی...: عبرانی۔ اضافہ کے ذریعے}\n9۔ جو قانون سننے سے کان ہٹاتا ہے، اس کی دعا بھی مکروہ ہوگی۔\n10۔ جو نیک لوگوں کو برائی میں گمراہ کرے گا، وہ اپنے ہی گڑھے میں گر جائے گا: لیکن نیک لوگ اچھائی کے مالک ہوں گے۔\n11۔ امیر آدمی اپنے غرور میں دانا ہے؛ لیکن جو غریب سمجھدار ہے وہ اسے تلاش کرتا ہے۔ {اپنے...: عبرانی۔ آنکھیں}\n12۔ جب نیک لوگ خوش ہوتے ہیں، تو عظیم جلال ہوتا ہے: لیکن جب بدکار اٹھتے ہیں تو انسان چھپا ہوتا ہے۔ {چھپا ہوا: یا، تلاش کیا گیا}\n13۔ جو اپنے گناہوں کو چھپاتا ہے وہ کامیاب نہیں ہوگا: لیکن جو اعتراف کرے اور چھوڑ دے اسے رحم ملے گا۔\n14. خوش باش وہ آدمی ہے جو ہمیشہ ڈرتا ہے: لیکن جو اپنا دل سخت کرتا ہے وہ شرارت میں گر جاتا ہے۔\n15۔ {ایس} ایک دہاڑتا ہوا شیر اور ایک گھومنے والا ریچھ؛ {اسی طرح} غریب لوگوں پر ظالم حکمران ہے۔\n16. جو شہزادہ سمجھنا چاہتا ہے {وہ بھی بڑا ظالم ہے}: {لیکن} جو لالچ سے نفرت کرتا ہے وہ {اپنی} کی عمر لمبا کرتا ہے۔\n17۔ جو شخص کسی کے خون پر ظلم کرے گا، وہ گڑھے میں بھاگ جائے گا؛ کوئی بھی اسے روک نہ سکے۔\n18۔ جو سیدھا چلے گا وہ نجات پائے گا: لیکن جو اپنے راستوں میں بگڑا ہوا ہے وہ فورا گر جائے گا۔\n19۔ جو اپنی زمین جوتتا ہے اسے وافر روٹی ملے گی؛ لیکن جو فضول لوگوں کے پیچھے جائے گا اس کے پاس کافی غربت ہوگی۔\n20۔ ایک وفادار آدمی نعمتوں سے بھرپور ہوگا: لیکن جو جلدی امیر ہونے کی کوشش کرے وہ بے گناہ نہیں ہوگا۔ {معصوم: یا، بغیر سزا کے}\n21. لوگوں کی عزت کرنا {ہے} اچھا نہیں: کیونکہ ایک روٹی کے ٹکڑے {وہ} کے لیے انسان زیادتی کرے گا۔\n22۔ جو امیر ہونے کی جلدی کرتا ہے اس کی نظر بری ہوتی ہے، اور وہ یہ نہیں سوچتا کہ اس پر غربت آ جائے گی۔ {جلدی...: یا، کیا کوئی بری نظر امیر ہونے کے لیے جلدی کرتی ہے}\n23. جو بعد میں کسی کو ملامت کرے گا، اسے زبان سے خوشامد کرنے والے سے زیادہ فضل ملے گا۔\n24۔ جو اپنے باپ یا ماں کو لوٹتا ہے اور کہتا ہے، {یہ کوئی گناہ نہیں}؛ یہی {ہے} ایک تباہ کن جہاز کا ساتھی ہے۔ {ایک تباہ کار: عبوری۔ ایک آدمی جو تباہ کر رہا ہے}\n25۔ جو مغرور دل کا ہے وہ جھگڑا پیدا کرتا ہے: لیکن جو خدا پر بھروسہ کرے گا وہ موٹا ہو جائے گا۔\n26. جو اپنے دل پر بھروسہ کرے وہ بیوقوف ہے: لیکن جو دانائی سے چلتا ہے، وہ نجات پائے گا۔\n27۔ جو غریبوں کو دیتا ہے وہ کمی نہیں کرے گا: لیکن جو اپنی آنکھیں چھپائے گا اس پر کئی لعنتیں ہوں گی۔\n28۔ جب بدکار اٹھتے ہیں تو لوگ خود کو چھپاتے ہیں: لیکن جب وہ مر جاتے ہیں تو نیک لوگ بڑھ جاتے ہیں۔","1۔ وہ جو اکثر سرزنش کا شکار ہوتا ہے اور اس کی گردن سخت کر لیتا ہے، اچانک تباہ ہو جائے گا، اور وہ بھی بغیر علاج کے۔ {وہ...: عبرانی۔ ملامت کرنے والا آدمی}\n2۔ جب نیک لوگ اقتدار میں ہوتے ہیں تو لوگ خوش ہوتے ہیں: لیکن جب بدکار حکمرانی کرتے ہیں تو لوگ سوگ مناتے ہیں۔ {میں...: یا، بڑھا ہوا}\n3۔ جو حکمت سے محبت کرتا ہے وہ اپنے باپ کو خوش کرتا ہے: لیکن جو فاحشہوں کے ساتھ رہتا ہے وہ اپنی دولت خرچ کرتا ہے۔\n4۔ بادشاہ فیصلے سے زمین قائم کرتا ہے: لیکن جو تحفے دیتا ہے وہ اسے گرا دیتا ہے۔ {وہ...: عبرانی۔ ایک قربانی کا آدمی}\n5۔ جو آدمی اپنے پڑوسی کی خوشامد کرتا ہے وہ اپنے پیروں کے لیے جال بچھاتا ہے۔\n6۔ ایک برے آدمی کی گناہ میں جال ہے: لیکن نیک گاتے ہیں اور خوش ہوتے ہیں۔\n7۔ نیک لوگ غریبوں کے مقصد کو دیکھتے ہیں: {لیکن} بدکار سمجھتے ہیں کہ وہ اسے نہیں جانتے۔\n8۔ حقارت کرنے والے لوگ شہر کو جال میں لے آتے ہیں: لیکن عقلمند لوگ غصے کو دور کر دیتے ہیں۔ {لاؤ...: یا، شہر کو آگ لگا دو}\n9۔ اگر کوئی عقلمند شخص ایک بے وقوف آدمی سے بحث کرے، چاہے وہ غصہ کرے یا ہنسے، تو آرام نہیں ہوتا۔\n10۔ خونخوار نیک لوگوں سے نفرت کرتے ہیں: لیکن عادل اس کی روح تلاش کرتے ہیں۔ {خونخوار: عبرانی۔ خون کے لوگ}\n11۔ ایک بیوقوف اپنا سارا دل کہتا ہے، لیکن ایک دانا اسے بعد میں رکھتا ہے۔\n12۔ اگر حکمران جھوٹ سنے، تو اس کے تمام خادم برے ہیں۔\n13۔ غریب اور دھوکہ باز ایک ساتھ ملتے ہیں: خداوند دونوں کی آنکھیں روشن کرتا ہے۔ {دھوکہ باز...: یا، سود خور}\n14۔ وہ بادشاہ جو وفاداری سے غریبوں کا فیصلہ کرے، اس کا تخت ہمیشہ کے لیے قائم ہوگا۔\n15۔ چھڑی اور سرزنش حکمت دیتے ہیں: لیکن ایک بچہ جو {اپنے لیے} رہ جاتا ہے وہ اپنی ماں کو شرمندہ کر دیتا ہے۔\n16۔ جب بدکاروں کی تعداد بڑھ جائے تو گناہ بڑھتا ہے: لیکن نیک لوگ ان کا زوال دیکھیں گے۔\n17۔ اپنے بیٹے کو درست کرو، اور وہ تمہیں آرام دے گا؛ ہاں، وہ تمہاری روح کو خوشی دے گا۔\n18۔ جہاں {کوئی رویا نہیں} وہاں لوگ ہلاک ہو جاتے ہیں: لیکن جو قانون کی پابندی کرتا ہے، وہ خوش نصیب ہے۔ {فنا: یا، ننگا ہو جاتا ہے}\n19۔ خادم کو الفاظ سے درست نہیں کیا جائے گا: کیونکہ چاہے وہ سمجھ جائے تو جواب نہیں دے گا۔\n20. کیا تم نے دیکھا ہے کہ کوئی آدمی [جو} اپنی باتوں میں جلد بازی کرتا ہے؟ ایک بے وقوف کی امید اس سے زیادہ ہے۔ {الفاظ: یا، اہم ہیں؟}\n21. جو اپنے خادم کو بچے سے نرمی سے پروان چڑھائے، وہ اسے اپنے بیٹے کے طور پر لے گا۔\n22۔ ایک غصے والا آدمی فساد کو جنم دیتا ہے، اور ایک غصے والا آدمی گناہوں میں مبتلا ہوتا ہے۔\n23. انسان کا غرور اسے نیچا دکھاتا ہے؛ لیکن عزت عاجز کو روح میں سہارا دیتی ہے۔\n24۔ جو چور کا ساتھی ہے وہ اپنی جان سے نفرت کرتا ہے: وہ لعنتیں سنتا ہے، اور اس پر افسوس نہیں کرتا۔\n25۔ انسان کا خوف جال لے آتا ہے: لیکن جو بھی خدا پر بھروسہ کرے گا وہ محفوظ ہوگا۔ {محفوظ: عببرانی۔ اونچی سطح پر سیٹ کیا گیا ہے}\n26. بہت سے لوگ حکمران کی خوشنودی چاہتے ہیں؛ لیکن {ہر انسان} کا فیصلہ {آتا ہے} خداوند کی طرف سے۔ {حکمران کا...: عبرانی۔ حکمران کا چہرہ}\n27. ظالم انسان نیک لوگوں کے لیے مکروہ ہے: اور جو سیدھا ہے وہ بدکاروں کے لیے مکروہ ہے۔","1۔ یاکہ کے بیٹے آگور کے الفاظ، {حتی} پیشن گوئی: اس آدمی نے ایتھیئل، حتیٰ کہ ایتھیل اور اوکال سے کہا،\n2. یقینا میں {کسی بھی} انسان سے زیادہ وحشی ہوں، اور کسی انسان کی سمجھ نہیں رکھتا۔\n3. میں نے نہ حکمت سیکھی، نہ ہی مقدس کا علم۔ {ہے: عبوری۔ جانیں}\n4۔ کون آسمان میں چڑھا یا نیچے آیا؟ کس نے ہوا کو اپنے ہاتھوں میں جمع کیا ہے؟ کس نے پانیوں کو لباس میں باندھا ہے؟ کس نے زمین کے تمام کناروں کو قائم کیا ہے؟ اس کا نام کیا ہے، اور اس کے بیٹے کا نام کیا ہے، اگر تم بتا سکتے ہو؟\n5۔ خدا کا ہر کلام {پاک} ہے: وہ {ہے} ان لوگوں کے لیے ایک ڈھال جو اس پر بھروسہ کرتے ہیں۔ {خالص: عبرانی۔ پاکیزہ}\n6۔ اس کی باتوں میں اضافہ نہ کرو، ورنہ وہ تمہیں ڈانٹ دے گا، اور تم جھوٹے ثابت ہو جاؤ گے۔\n7. میں نے تم سے دو {چیزیں} مانگی ہیں؛ مجھے انکار کرو {انہیں} اس سے پہلے کہ میں مر جاؤں: {انکار...: عبرانی۔ مجھ سے نہ روکیں}\n8. میرے لیے خود پسندی اور جھوٹ کو دور کرو: مجھے غربت اور دولت نہ دو؛ مجھے وہ کھانا کھلائیں جو میرے لیے آسان ہو: {آسان...: عبرانی۔ میری جیب خرچ سے}\n9۔ کہیں میں مکمل نہ ہو جاؤں، اور تمہیں انکار کروں اور کہوں، خداوند کون ہے؟ یا کہیں میں غریب نہ ہو جاؤں، چوری نہ کروں، اور اپنے خدا کا نام لے لوں {بے سود}۔ {انکار...: عبرانی۔ جھوٹ ہے}\n10۔ کسی خادم کو اس کے مالک پر الزام نہ دو، ورنہ وہ تمہیں لعنت دے گا اور تم مجرم ثابت ہو جاؤ گے۔ {الزام...: عبرانی۔ اپنی زبان سے تکلیف نہ دینا}\n11۔ {ایک نسل ہے} جو اپنے والد کو لعنت دیتی ہے، اور اپنی ماں کو برکت نہیں دیتی۔\n12. {ایک نسل ہے} جو {اپنی آنکھوں میں} پاک ہے، اور {ابھی} اپنی گندگی سے نہیں مٹی ہوئی۔\n13. {ایک نسل} ہے، اے ان کی آنکھیں کتنی بلند ہیں! اور ان کی پلکیں اوپر اٹھائی جاتی ہیں۔\n14۔ ایک نسل ہے، جس کے دانت تلواروں کی مانند ہیں، اور ان کے جبڑے کے دانت چھریوں کی طرح ہیں، جو زمین سے غریبوں کو اور محتاجوں کو مردوں میں سے نگل جاتی ہے۔\n15۔ گھوڑے کے دو بیٹیاں ہیں، {روتے ہوئے}، دو، دو۔ تین {چیزیں} ایسی ہیں جو کبھی مطمئن نہیں ہوتیں، {ہاں}، چار {چیزیں} نہیں کہتیں، {یہ کافی ہے}: {یہ ہے...: عبرانی۔ دولت}\n16۔ قبر؛ اور بانجھ رحم؛ زمین {جو} پانی سے بھری نہیں ہوتی؛ اور وہ آگ {جو} نہیں کہتی، {بس} کافی ہے۔\n17۔ وہ آنکھ {جو} اس کے والد کا مذاق اڑاتی ہے، اور {اپنی} کی ماں کی اطاعت سے نفرت کرتی ہے، وادی کے کوا اسے نکال لیں گے، اور نوجوان عقاب اسے کھائیں گے۔ {وادی: یا، ندی نال}\n18. تین {چیزیں} ہیں جو میرے لیے بہت شاندار ہیں، ہاں، چار جو مجھے معلوم نہیں:\n19۔ ہوا میں عقاب کا راستہ؛ ایک چٹان پر سانپ کا راستہ؛ سمندر کے بیچ میں جہاز کا راستہ؛ اور ایک آدمی کا طریقہ جس کی نوکرانی ہو۔ {درمیان: عبوری۔ دل}\n20. یہی ایک کرنے والی عورت کا طریقہ ہے؛ وہ کھاتی ہے، اپنا منہ صاف کرتی ہے، اور کہتی ہے، میں نے کوئی برا کام نہیں کیا۔\n21۔ تین {چیز} کے لیے زمین بے چین ہے، اور چار {جو} کے لیے وہ برداشت نہیں کر سکتی:\n22۔ خادم کے لیے جب وہ حکومت کرتا ہے؛ اور جب وہ گوشت سے بھر جائے تو بیوقوف بن جاتا ہے؛\n23۔ ایک نفرت انگیز {عورت} کے لیے جب وہ شادی شدہ ہو؛ اور ایک خادمہ جو اپنی محبوبہ کی وارث ہے۔\n24. زمین پر چار {چیزیں ہیں جو کم ہیں}، لیکن وہ {انتہائی دانا} ہیں: {سے زیادہ...: عبرانی۔ عقلمند، عقلمند بنایا گیا}\n25. چیونٹیاں ایک ایسی قوم ہیں جو مضبوط نہیں ہیں، پھر بھی گرمیوں میں اپنا گوشت تیار کرتی ہیں؛\n26. کونیز کمزور قوم ہیں، پھر بھی وہ چٹانوں میں اپنے گھر بناتے ہیں؛\n27۔ ٹڈی دل کا کوئی بادشاہ نہیں، پھر بھی وہ سب گروہوں کی صورت میں باہر نکلتے ہیں؛ {بذریعہ...: عبرانی۔ اکٹھے ہوئے}\n28۔ مکڑی اپنے ہاتھوں سے پکڑتی ہے، اور بادشاہوں کے محلوں میں ہے۔\n29۔ تین {چیزیں} ہیں جو اچھی چلتی ہیں، ہاں، چار خوبصورت ہیں:\n30۔ ایک شیر {جو} جانوروں میں سب سے طاقتور ہے، اور کسی کے لیے نہیں مڑتا؛\n31۔ ایک گری ہاؤنڈ؛ اور بکری بھی؛ اور ایک بادشاہ، جس کے خلاف کوئی بغاوت نہیں ہوتی۔ {گری ہاؤنڈ: یا، گھوڑا: ہیب۔ کمر میں گرٹ}\n32۔ اگر تم نے خود کو اٹھا کر بے وقوفی کی ہے، یا اگر تم نے برا سوچا ہے، تو اپنا ہاتھ اپنے منہ پر رکھو۔\n33۔ یقینا دودھ کی مچل مکھن پیدا کرتی ہے، اور ناک کی مروڑنے سے خون نکلتا ہے: اسی طرح غصے کی طاقت فساد کو جنم دیتی ہے۔","1۔ بادشاہ لیموئیل کے الفاظ، وہ پیش گوئی جو اس کی ماں نے اسے سکھائی تھی۔\n2. کیا، میرے بیٹے؟ اور کیا، میرے رحم کا بیٹا؟ اور کیا، میرے وعدوں کا بیٹا؟\n3۔ اپنی طاقت عورتوں کو نہ دو، نہ اپنی راہیں اس چیز کو دو جو بادشاہوں کو تباہ کرتی ہے۔\n4. بادشاہوں کے لیے نہیں، اے لیموئیل، بادشاہوں کے لیے شراب پینا مناسب نہیں؛ نہ ہی شہزادوں کے لیے تیز مشروب:\n5۔ تاکہ وہ شراب نہ پیتیں، قانون کو بھول جائیں، اور کسی بھی متاثرہ کے فیصلے کو بگاڑ نہ دیں۔ {پرورٹ: عبرانی۔ alter} {کسی بھی...: عبرانی۔ تمام مصیبت کے بیٹوں میں}\n6۔ جو فنا کے لیے تیار ہے اسے تیز پانی دو، اور دل بھاری رکھنے والوں کو شراب۔ {of...: عبرانی۔ روح کی کڑوا}\n7۔ اسے پینے دو، اپنی غربت کو بھول جائے، اور اپنی بدحالی کو مزید یاد نہ رکھے۔\n8. اپنے منہ کو ان سب کے لیے کھولوں جو تباہی کے لیے مقرر کیے گئے ہیں، ان سب کے لیے جو تباہی کے لیے مقرر کیے گئے ہیں۔ {ایسا...: عبرانی۔ تباہی کے بیٹے}\n9۔ اپنا منہ کھولو، راستبازی سے فیصلہ کرو، اور غریبوں اور محتاجوں کے حق میں آواز اٹھاؤ۔\n10۔ کون نیک عورت تلاش کر سکتا ہے؟ اس کی قیمت {ہے} یاقوت سے کہیں زیادہ۔\n11۔ اس کے شوہر کا دل اس پر اعتماد کرتا ہے، تاکہ اسے لوٹ مار کی ضرورت نہ پڑے۔\n12۔ وہ اپنی زندگی کے تمام دنوں اس کے لیے بھلائی کرے گی اور برا نہیں۔\n13۔ وہ اون اور فلیس تلاش کرتی ہے، اور اپنے ہاتھوں سے خوشی سے کام کرتی ہے۔\n14۔ وہ تاجروں کے جہازوں کی طرح ہے؛ وہ دور سے اپنا کھانا لاتی ہے۔\n15۔ وہ رات کے وقت بھی اٹھتی ہے، اور اپنے گھرانے کو گوشت دیتی ہے، اور اپنی لڑکیوں کو ایک حصہ دیتی ہے۔\n16۔ وہ ایک کھیت دیکھتی ہے اور اسے خریدتی ہے: اپنے ہاتھوں کے پھل سے انگور کا باغ لگاتی ہے۔ {buyeth: Hebrew. ٹیکتھ}\n17۔ وہ اپنی کمر کو مضبوطی سے باندھتی ہے، اور اپنے بازو مضبوط کرتی ہے۔\n18۔ وہ محسوس کرتی ہے کہ اس کا سامان اچھا ہے: اس کی موم بتی رات کو بجھتی نہیں۔ {وہ...: عبرانی۔ وہ چکھتی ہے}\n19۔ وہ اپنے ہاتھ اسپنڈل پر رکھتی ہے، اور اس کے ہاتھ ڈسٹاف کو تھامے ہوئے ہیں۔\n20۔ وہ غریبوں کی طرف ہاتھ بڑھاتی ہے؛ ہاں، وہ اپنے ہاتھ ضرورت مندوں کی طرف بڑھاتی ہے۔ {وہ...: عبرانی۔ وہ پھیلتی ہے}\n21۔ وہ اپنے گھر کے لیے برف سے نہیں ڈرتی: کیونکہ اس کے تمام گھرانے سرخ لباس میں ملبوس ہیں۔ {اسکارلٹ: یا، ڈبل گارمنٹس}\n22۔ وہ اپنے لیے قالین کے ڈھانپے بناتی ہے؛ اس کے کپڑے ریشم اور جامنی رنگ کے ہیں۔\n23۔ اس کا شوہر دروازوں پر جانا جاتا ہے، جب وہ ملک کے بزرگوں کے درمیان بیٹھا ہوتا ہے۔\n24۔ وہ عمدہ کپڑا بناتی ہے، اور بیچتی ہے؛ اور تاجر کو بیلٹ پہنچاتا ہے۔\n25. طاقت اور عزت اس کے لباس ہیں؛ اور وہ آنے والے وقت پر خوش ہوگی۔\n26۔ وہ حکمت سے اپنا منہ کھولتی ہے؛ اور اس کی زبان میں مہربانی کا قانون ہے۔\n27۔ وہ اپنے گھرانے کے طریقوں پر اچھی طرح نظر رکھتی ہے، اور سستی کی روٹی نہیں کھاتی۔\n28۔ اس کے بچے اٹھتے ہیں اور اسے مبارک کہتے ہیں؛ اس کا شوہر بھی، اور وہ اس کی تعریف کرتا ہے۔\n29۔ بہت سی بیٹیوں نے نیکی کی ہے، لیکن تم سب سے بہتر ہو۔ {کیا ہے...: یا، دولت حاصل کی ہے}\n30۔ فضل دھوکہ ہے، اور خوبصورتی فضول ہے: لیکن جو عورت خدا سے ڈرتی ہے، اس کی تعریف کی جائے گی۔\n31۔ اسے اس کے ہاتھوں کے پھل سے دے دو؛ اور اپنے کاموں کو دروازوں پر اس کی تعریف کرنے دیں۔"];
